-- IELTS vocabulary band library
-- Generated from prisma/vocabulary-data/*.txt. Do not edit this SQL by hand.

ALTER TABLE "VocabularyTopic"
ADD COLUMN IF NOT EXISTS "isSupplementary" BOOLEAN NOT NULL DEFAULT false;

DO $$
DECLARE
  legacy_group_id TEXT;
  target_group_id TEXT;
  legacy_topic_id TEXT;
  target_topic_id TEXT;
BEGIN
  SELECT "id" INTO legacy_group_id FROM "VocabularyGroup" WHERE "name" = 'Academic Vocabulary' LIMIT 1;
  SELECT "id" INTO target_group_id FROM "VocabularyGroup" WHERE "name" = 'Nhóm 2 - Phát triển Band 5.0-6.5' LIMIT 1;
  IF legacy_group_id IS NOT NULL AND target_group_id IS NULL THEN
    UPDATE "VocabularyGroup" SET "name" = 'Nhóm 2 - Phát triển Band 5.0-6.5', "sortOrder" = 20, "updatedAt" = NOW() WHERE "id" = legacy_group_id;
  END IF;

  SELECT t."id" INTO legacy_topic_id
  FROM "VocabularyTopic" t
  JOIN "VocabularyGroup" g ON g."id" = t."groupId"
  WHERE g."name" = 'Nhóm 2 - Phát triển Band 5.0-6.5' AND t."name" = 'Environment' LIMIT 1;
  SELECT t."id" INTO target_topic_id
  FROM "VocabularyTopic" t
  JOIN "VocabularyGroup" g ON g."id" = t."groupId"
  WHERE g."name" = 'Nhóm 2 - Phát triển Band 5.0-6.5' AND t."name" = 'Environment & Energy' LIMIT 1;
  IF legacy_topic_id IS NOT NULL AND target_topic_id IS NULL THEN
    UPDATE "VocabularyTopic" SET "name" = 'Environment & Energy', "updatedAt" = NOW() WHERE "id" = legacy_topic_id;
  END IF;
END $$;

