  ('vg_band_3', 'Nhóm 3 - Nâng cao Band 6.5+', 30, NOW(), NOW())
ON CONFLICT ("name") DO UPDATE SET "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = NOW();

