INSERT INTO "VocabularyTopic" ("id", "groupId", "name", "sortOrder", "isSupplementary", "createdAt", "updatedAt")
SELECT
  'vt_' || md5(td."groupKey" || '|' || td."name"),
  g."id", td."name", td."sortOrder", td."isSupplementary", NOW(), NOW()
FROM topic_data td
JOIN "VocabularyGroup" g ON g."name" = td."groupName"
ON CONFLICT ("groupId", "name") DO UPDATE SET
  "sortOrder" = EXCLUDED."sortOrder",
  "isSupplementary" = EXCLUDED."isSupplementary",
  "updatedAt" = NOW();

