"synonyms":["atmosphere"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Environment Basics","word":"protect","meaning":"to keep someone or something safe from harm","translation":"bảo vệ","example":"Laws can help protect endangered animals.","synonyms":["defend"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Environment Basics","word":"damage","meaning":"harm that makes something worse or less useful","translation":"thiệt hại","example":"Heavy tourism can damage fragile natural areas.","synonyms":["harm"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Environment Basics","word":"climate","meaning":"the usual weather conditions of a place","translation":"khí hậu","example":"The local climate affects farming and water use.","synonyms":["weather pattern"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Environment Basics","word":"resource","meaning":"a useful supply of something","translation":"tài nguyên","example":"Water is an essential natural resource.","synonyms":["supply"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Transport","word":"transport","meaning":"systems used to move people or goods","translation":"giao thông vận tải","example":"Good transport links can improve access to jobs.","synonyms":["transportation"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Transport","word":"traffic","meaning":"vehicles moving on roads","translation":"giao thông","example":"Heavy traffic causes delays during rush hour.","synonyms":["road traffic"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Transport","word":"car","meaning":"a road vehicle for a small number of people","translation":"ô tô","example":"Many families depend on a car for daily travel.","synonyms":["automobile"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Transport","word":