s":["rural settlement"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Housing & Cities","word":"neighbourhood","meaning":"an area of a town or city where people live","translation":"khu dân cư","example":"A quiet neighbourhood can be attractive to families.","synonyms":["local area"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Housing & Cities","word":"rent","meaning":"money paid regularly to use a home owned by someone else","translation":"tiền thuê","example":"High rent can make city life difficult for low-income workers.","synonyms":["rental payment"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Housing & Cities","word":"population","meaning":"the number of people living in a place","translation":"dân số","example":"The city's population has grown quickly.","synonyms":["residents"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Housing & Cities","word":"building","meaning":"a structure with walls and a roof","translation":"tòa nhà","example":"Old buildings may need repairs to remain safe.","synonyms":["structure"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Housing & Cities","word":"crowded","meaning":"full of too many people or things","translation":"đông đúc","example":"Public spaces can become crowded during festivals.","synonyms":["packed"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Housing & Cities","word":"local","meaning":"connected with a particular nearby area","translation":"địa phương","example":"Local authorities should maintain parks and roads.","synonyms":["nearby"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Housing & Cities","word":"move","meaning":"to change the place where one lives","translation":"chuyển nhà","example":"Families may move to find cheaper housing.","synonyms":["relocate"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền