ocery store"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"store","meaning":"a place where goods are sold","translation":"cửa hàng","example":"The store offers discounts to regular customers.","synonyms":["shop"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"online shopping","meaning":"buying goods through the internet","translation":"mua sắm trực tuyến","example":"Online shopping is convenient but can encourage unnecessary spending.","synonyms":["internet shopping"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"delivery","meaning":"the act of taking goods to a person or place","translation":"giao hàng","example":"Fast delivery is important for many online customers.","synonyms":["shipment"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"cashier","meaning":"a worker who receives payments in a shop","translation":"thu ngân","example":"Automated systems are replacing some cashier jobs.","synonyms":["checkout worker"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"discount","meaning":"a reduction in the normal price","translation":"giảm giá","example":"Large discounts can encourage people to buy more.","synonyms":["price reduction"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"brand","meaning":"a name used to identify a company's products","translation":"thương hiệu","example":"Some consumers pay more for a well-known brand.","synonyms":["trade name"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"quality","meaning":"how good or bad something is","translation":"chất lượng","example":"Customers usually expect higher quality when prices are high.","synonyms":["standard"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"return","meaning":"to take a product back to a shop","translation":"trả lại hàng","example":"Customers should be able to return faulty goods.","synonyms":["give back"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"repair","meaning":"to fix something that is broken","translation":"sửa chữa","example":"Repairing electronics can reduce waste.","synonyms":["fix"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Shopping & Services","word":"payment","meaning":"money given in exchange for goods or services","translation":"thanh toán","example":"Digital payment methods are common in modern shops.","synonyms":["transaction"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"curriculum","meaning":"the subjects and content taught in an education programme","translation":"chương trình học","example":"Universities should update the curriculum to match changing workplace needs.","synonyms":["course content"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"tuition fees","meaning":"money charged for teaching at a college or university","translation":"học phí","example":"High tuition fees can discourage students from low-income families.","synonyms":["education fees"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"scholarship","meaning":"money awarded to help a student pay for education","translation":"học bổng","example":"Scholarships can widen access to higher education.","synonyms":["study grant"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"undergraduate","meaning":"a student studying for a first university degree","translation":"sinh viên bậc đại học","example":"Many undergraduates combine study with part-time employment.","synonyms":["degree student"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"postgraduate","meaning":"a student studying after completing a first degree","translation":"học viên sau đại học","example":"Postgraduate study often requires independent research.","synonyms":["graduate student"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"academic performance","meaning":"how well a student performs in formal study","translation":"thành tích học tập","example":"Sleep and study habits can affect academic performance.","synonyms":["study results"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"vocational education","meaning":"education that prepares people for a specific trade or occupation","translation":"giáo dục nghề nghiệp","example":"Vocational education can provide a direct route into skilled employment.","synonyms":["career training"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"practical skills","meaning":"abilities used to perform real tasks effectively","translation":"kỹ năng thực hành","example":"Employers often value practical skills as well as academic knowledge.","synonyms":["hands-on skills"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"critical thinking","meaning":"the ability to analyse ideas and judge evidence carefully","translation":"tư duy phản biện","example":"Higher education should develop students' critical thinking.","synonyms":["analytical thinking"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"distance learning","meaning":"education completed away from a physical classroom","translation":"học từ xa","example":"Distance learning gives working adults greater flexibility.","synonyms":["remote education"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"assessment","meaning":"a method of measuring knowledge or performance","translation":"đánh giá","example":"Continuous assessment can reduce pressure from final exams.","synonyms":["evaluation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"qualification","meaning":"an official record showing that someone completed education or training","translation":"bằng cấp","example":"Professional qualifications may improve employment prospects.","synonyms":["credential"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"campus","meaning":"the buildings and grounds of a university or college","translation":"khuôn viên trường","example":"A well-designed campus can support both study and social life.","synonyms":["university grounds"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Higher Education","word":"compulsory education","meaning":"education that children are legally required to receive","translation":"giáo dục bắt buộc","example":"Compulsory education helps ensure basic literacy for all children.","synonyms":["mandatory schooling"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"workforce","meaning":"all the people available to work in a country or organisation","translation":"lực lượng lao động","example":"An ageing workforce can create labour shortages.","synonyms":["labour force"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"productivity","meaning":"the amount of useful work produced in a given time","translation":"năng suất","example":"Better training can increase workplace productivity.","synonyms":["efficiency"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"promotion","meaning":"a move to a more senior position at work","translation":"thăng chức","example":"Clear promotion opportunities can motivate employees.","synonyms":["advancement"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"job satisfaction","meaning":"the feeling of being pleased with one's work","translation":"sự hài lòng trong công việc","example":"Flexible hours can improve job satisfaction.","synonyms":["work satisfaction"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"flexible working","meaning":"work arrangements that allow changes in time or location","translation":"làm việc linh hoạt","example":"Flexible working can help parents manage family duties.","synonyms":["flexible employment"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"remote work","meaning":"paid work completed away from a traditional workplace","translation":"làm việc từ xa","example":"Remote work reduces commuting time for many employees.","synonyms":["working from home"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"work-life balance","meaning":"a healthy division of time between work and personal life","translation":"cân bằng công việc và cuộc sống","example":"Long working hours can damage work-life balance.","synonyms":["life-work balance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"recruitment","meaning":"the process of finding and hiring workers","translation":"tuyển dụng","example":"Online recruitment allows companies to reach more applicants.","synonyms":["hiring"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"internship","meaning":"a temporary period of work for gaining experience","translation":"thực tập","example":"An internship can help graduates understand a profession.","synonyms":["work placement"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"profession","meaning":"a type of skilled occupation requiring training or education","translation":"nghề nghiệp chuyên môn","example":"Medicine is a profession that requires years of study.","synonyms":["occupation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"workload","meaning":"the amount of work a person is expected to do","translation":"khối lượng công việc","example":"An excessive workload can lead to stress and burnout.","synonyms":["amount of work"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"shift work","meaning":"work organised into different periods of the day or night","translation":"làm việc theo ca","example":"Shift work can disrupt normal sleep patterns.","synonyms":["rotating work"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"job security","meaning":"the likelihood that a person will keep their job","translation":"sự ổn định việc làm","example":"Permanent contracts usually provide greater job security.","synonyms":["employment stability"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Employment & Workplace","word":"self-employed","meaning":"working for oneself rather than an employer","translation":"tự kinh doanh","example":"Self-employed workers often have more control over their schedules.","synonyms":["independent worker"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"healthcare","meaning":"services for maintaining and improving people's health","translation":"chăm sóc sức khỏe","example":"Affordable healthcare can reduce inequality in health outcomes.","synonyms":["medical care"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"obesity","meaning":"the condition of having an unhealthy amount of body fat","translation":"béo phì","example":"Childhood obesity is linked to diet and low physical activity.","synonyms":["severe overweight"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"vaccination","meaning":"the use of a vaccine to protect against disease","translation":"tiêm chủng","example":"Vaccination programmes can prevent the spread of infectious diseases.","synonyms":["immunisation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"prevention","meaning":"action taken to stop a problem or disease before it occurs","translation":"phòng ngừa","example":"Prevention is often cheaper than treating serious illness.","synonyms":["avoidance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"mental health","meaning":"a person's emotional and psychological condition","translation":"sức khỏe tinh thần","example":"Schools are paying more attention to students' mental health.","synonyms":["psychological well-being"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"sedentary lifestyle","meaning":"a way of life involving very little physical activity","translation":"lối sống ít vận động","example":"A sedentary lifestyle increases the risk of several health problems.","synonyms":["inactive lifestyle"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"balanced diet","meaning":"a diet containing suitable amounts of different nutrients","translation":"chế độ ăn cân bằng","example":"A balanced diet is important for long-term health.","synonyms":["healthy diet"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"life expectancy","meaning":"the average number of years a person is expected to live","translation":"tuổi thọ","example":"Improved sanitation has increased life expectancy in many countries.","synonyms":["expected lifespan"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"healthcare access","meaning":"the ability to obtain medical services when needed","translation":"khả năng tiếp cận y tế","example":"Rural communities may have limited healthcare access.","synonyms":["access to care"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"medical staff","meaning":"people who work professionally in healthcare","translation":"nhân viên y tế","example":"Hospitals need enough medical staff to provide safe treatment.","synonyms":["health workers"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"public awareness","meaning":"general knowledge and understanding among the public","translation":"nhận thức cộng đồng","example":"Public awareness campaigns can encourage healthier behaviour.","synonyms":["social awareness"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"addiction","meaning":"a strong dependence on a substance or activity","translation":"nghiện","example":"Digital addiction can interfere with sleep and study.","synonyms":["dependence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"well-being","meaning":"the state of being healthy, comfortable and satisfied","translation":"sức khỏe và hạnh phúc","example":"Green spaces can improve residents' well-being.","synonyms":["welfare"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Public Health","word":"chronic disease","meaning":"a health condition that lasts for a long time","translation":"bệnh mãn tính","example":"Regular exercise can reduce the risk of chronic disease.","synonyms":["long-term illness"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"digital literacy","meaning":"the ability to use digital tools safely and effectively","translation":"năng lực số","example":"Schools should teach digital literacy from an early age.","synonyms":["digital competence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"privacy","meaning":"the right to keep personal information and life protected","translation":"quyền riêng tư","example":"Social media users should understand online privacy risks.","synonyms":["personal privacy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"cyberbullying","meaning":"bullying carried out through digital technology","translation":"bắt nạt trên mạng","example":"Cyberbullying can seriously affect teenagers' mental health.","synonyms":["online bullying"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"screen time","meaning":"time spent using phones, computers or other screens","translation":"thời gian sử dụng màn hình","example":"Parents often worry about children's excessive screen time.","synonyms":["device time"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"online learning","meaning":"education delivered through the internet","translation":"học trực tuyến","example":"Online learning can improve access for students in remote areas.","synonyms":["e-learning"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"virtual communication","meaning":"communication that takes place through digital systems","translation":"giao tiếp trực tuyến","example":"Virtual communication is convenient but may feel less personal.","synonyms":["online interaction"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"content creator","meaning":"a person who produces material for online audiences","translation":"nhà sáng tạo nội dung","example":"Some young people hope to become professional content creators.","synonyms":["online creator"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"internet access","meaning":"the ability to connect to and use the internet","translation":"khả năng truy cập internet","example":"Reliable internet access is essential for many students.","synonyms":["online access"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"digital divide","meaning":"the gap between people with and without effective access to digital technology","translation":"khoảng cách số","example":"The digital divide can deepen educational inequality.","synonyms":["technology gap"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"online platform","meaning":"a digital service where users interact or access content","translation":"nền tảng trực tuyến","example":"Online platforms have changed how people shop and communicate.","synonyms":["digital platform"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"user data","meaning":"information collected about people who use a digital service","translation":"dữ liệu người dùng","example":"Companies should protect user data from misuse.","synonyms":["personal data"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"e-commerce","meaning":"buying and selling goods and services online","translation":"thương mại điện tử","example":"E-commerce allows small businesses to reach national markets.","synonyms":["online trade"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"streaming service","meaning":"an online service that delivers video or audio on demand","translation":"dịch vụ phát trực tuyến","example":"Streaming services have changed viewing habits.","synonyms":["on-demand service"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Digital Life & Social Media","word":"mobile application","meaning":"software designed to run on a smartphone or tablet","translation":"ứng dụng di động","example":"A mobile application can make public services easier to access.","synonyms":["app"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"sustainable","meaning":"able to continue without causing serious environmental harm","translation":"bền vững","example":"Cities need sustainable transport and housing policies.","synonyms":["environmentally sound"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"biodiversity","meaning":"the variety of living species in an area","translation":"đa dạng sinh học","example":"Deforestation can cause major losses of biodiversity.","synonyms":["biological diversity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"pollution","meaning":"harmful contamination of air, water or land","translation":"ô nhiễm","example":"Industrial pollution can damage both ecosystems and human health.","synonyms":["contamination"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"renewable energy","meaning":"energy from sources that can naturally be replaced","translation":"năng lượng tái tạo","example":"Renewable energy can reduce dependence on fossil fuels.","synonyms":["clean energy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"fossil fuel","meaning":"coal, oil or gas formed from ancient organic matter","translation":"nhiên liệu hóa thạch","example":"Burning fossil fuels releases large amounts of carbon dioxide.","synonyms":["coal oil and gas"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"carbon emissions","meaning":"carbon gases released into the atmosphere","translation":"khí thải carbon","example":"Public transport can help reduce carbon emissions.","synonyms":["carbon output"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"greenhouse gas","meaning":"a gas that traps heat in the atmosphere","translation":"khí nhà kính","example":"Governments are setting targets to cut greenhouse gas emissions.","synonyms":["heat-trapping gas"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"deforestation","meaning":"the large-scale removal of forests","translation":"nạn phá rừng","example":"Deforestation threatens wildlife and increases soil erosion.","synonyms":["forest loss"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"conservation","meaning":"the protection of nature and natural resources","translation":"bảo tồn","example":"Wildlife conservation requires long-term funding.","synonyms":["protection of nature"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"recycling","meaning":"the process of turning waste into reusable material","translation":"tái chế","example":"Effective recycling systems can reduce landfill waste.","synonyms":["material recovery"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"environmental impact","meaning":"the effect of an activity on the natural environment","translation":"tác động môi trường","example":"New infrastructure should be assessed for environmental impact.","synonyms":["ecological effect"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"natural resources","meaning":"materials from nature that people can use","translation":"tài nguyên thiên nhiên","example":"Countries must manage natural resources carefully.","synonyms":["natural assets"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"energy efficiency","meaning":"using less energy to achieve the same result","translation":"hiệu quả năng lượng","example":"Better insulation can improve household energy efficiency.","synonyms":["efficient energy use"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Environment & Energy","word":"climate change","meaning":"long-term changes in global or regional climate","translation":"biến đổi khí hậu","example":"Climate change is increasing the frequency of extreme weather.","synonyms":["global warming"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"urbanisation","meaning":"the growth of cities as more people live in urban areas","translation":"đô thị hóa","example":"Rapid urbanisation creates pressure on housing and transport.","synonyms":["city growth"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"housing shortage","meaning":"a lack of enough homes for the population","translation":"thiếu nhà ở","example":"A housing shortage can push rents higher.","synonyms":["lack of housing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"affordable housing","meaning":"homes that people on normal incomes can reasonably pay for","translation":"nhà ở giá phải chăng","example":"Cities need more affordable housing near employment centres.","synonyms":["low-cost housing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"urban sprawl","meaning":"the uncontrolled spread of a city into surrounding land","translation":"đô thị lan rộng","example":"Urban sprawl can increase car dependence.","synonyms":["city expansion"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"infrastructure","meaning":"basic systems such as roads, water and power needed by society","translation":"cơ sở hạ tầng","example":"Population growth requires investment in infrastructure.","synonyms":["public infrastructure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"residential area","meaning":"a part of a town or city mainly used for housing","translation":"khu dân cư","example":"New residential areas should include schools and parks.","synonyms":["housing district"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"living standards","meaning":"the level of comfort and material well-being people experience","translation":"mức sống","example":"Economic growth does not always improve living standards equally.","synonyms":["quality of life"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"overcrowding","meaning":"a situation where too many people live in a limited space","translation":"quá tải dân cư","example":"Overcrowding can place pressure on public services.","synonyms":["excess crowding"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"city centre","meaning":"the central business and commercial part of a city","translation":"trung tâm thành phố","example":"Housing in the city centre is often expensive.","synonyms":["downtown"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"rural area","meaning":"land and communities outside large towns and cities","translation":"khu vực nông thôn","example":"Young adults often leave rural areas for better job opportunities.","synonyms":["countryside"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"migration to cities","meaning":"the movement of people from other areas into urban centres","translation":"di cư vào thành phố","example":"Migration to cities can create both economic growth and congestion.","synonyms":["urban migration"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"property prices","meaning":"the amount of money homes and land cost","translation":"giá bất động sản","example":"Property prices have risen faster than incomes in many capitals.","synonyms":["housing prices"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"public facilities","meaning":"buildings and services available for community use","translation":"cơ sở công cộng","example":"New housing developments should include adequate public facilities.","synonyms":["community amenities"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Urbanisation & Housing","word":"green space","meaning":"an area of grass, trees or plants in a town or city","translation":"không gian xanh","example":"Green spaces can reduce heat and improve mental health.","synonyms":["urban greenery"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"commuter","meaning":"a person who regularly travels between home and work or study","translation":"người đi làm hằng ngày","example":"Commuters benefit from reliable train services.","synonyms":["daily traveller"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"rail network","meaning":"a connected system of railway lines","translation":"mạng lưới đường sắt","example":"Expanding the rail network can reduce road traffic.","synonyms":["rail system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"road safety","meaning":"measures and conditions that reduce traffic injuries","translation":"an toàn đường bộ","example":"Stricter speed limits can improve road safety.","synonyms":["traffic safety"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"cycle lane","meaning":"a part of a road reserved for bicycles","translation":"làn đường xe đạp","example":"Protected cycle lanes encourage more people to ride.","synonyms":["bike lane"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"pedestrian","meaning":"a person travelling on foot","translation":"người đi bộ","example":"City centres should be safer for pedestrians.","synonyms":["walker"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"rush hour","meaning":"the busiest travel period at the start or end of the working day","translation":"giờ cao điểm","example":"Buses are often crowded during rush hour.","synonyms":["peak travel time"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"transport system","meaning":"the network used to move people and goods","translation":"hệ thống giao thông","example":"An efficient transport system supports economic activity.","synonyms":["transit system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"public transit","meaning":"shared transport services such as buses and trains","translation":"giao thông công cộng","example":"Affordable public transit can improve access to employment.","synonyms":["mass transport"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"fuel consumption","meaning":"the amount of fuel used by vehicles or machines","translation":"mức tiêu thụ nhiên liệu","example":"Smaller cars often have lower fuel consumption.","synonyms":["fuel use"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"electric vehicle","meaning":"a vehicle powered mainly by electricity","translation":"xe điện","example":"Electric vehicles can reduce local air pollution.","synonyms":["EV"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"parking space","meaning":"an area where a vehicle can be left","translation":"chỗ đỗ xe","example":"Limited parking spaces may discourage car use in city centres.","synonyms":["parking spot"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"transport investment","meaning":"money spent to improve transport systems","translation":"đầu tư giao thông","example":"Transport investment should focus on long-term public needs.","synonyms":["transit funding"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"road network","meaning":"the connected system of roads in an area","translation":"mạng lưới đường bộ","example":"A stronger road network can improve rural access to markets.","synonyms":["road system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Transport & Infrastructure","word":"travel time","meaning":"the amount of time needed to complete a journey","translation":"thời gian di chuyển","example":"Better rail services can reduce travel time between cities.","synonyms":["journey time"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"offender","meaning":"a person who commits a crime","translation":"người phạm tội","example":"Young offenders may benefit from education and counselling.","synonyms":["lawbreaker"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"punishment","meaning":"a penalty given for breaking a law or rule","translation":"hình phạt","example":"Punishment should be proportionate to the seriousness of the crime.","synonyms":["penalty"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"rehabilitation","meaning":"help that enables an offender to return to normal society","translation":"cải tạo, phục hồi","example":"Rehabilitation can reduce the risk of future crime.","synonyms":["reform"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"juvenile crime","meaning":"illegal behaviour committed by young people","translation":"tội phạm vị thành niên","example":"Family support may help prevent juvenile crime.","synonyms":["youth crime"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"law enforcement","meaning":"the organisations and actions used to make people obey the law","translation":"thực thi pháp luật","example":"Effective law enforcement depends on public trust.","synonyms":["policing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"prison sentence","meaning":"a period that an offender must spend in prison","translation":"án tù","example":"Serious violent offences may result in a long prison sentence.","synonyms":["jail term"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"community service","meaning":"unpaid work ordered as a punishment or done for public benefit","translation":"lao động công ích","example":"Community service can be suitable for some minor offences.","synonyms":["unpaid public work"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"reoffend","meaning":"to commit another crime after being punished","translation":"tái phạm","example":"Training and employment may reduce the chance that prisoners reoffend.","synonyms":["commit crime again"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"deterrent","meaning":"something intended to discourage harmful or illegal behaviour","translation":"biện pháp răn đe","example":"High fines can act as a deterrent to dangerous driving.","synonyms":["discouragement"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"legal system","meaning":"the institutions and rules used to apply law","translation":"hệ thống pháp luật","example":"A fair legal system should treat people equally.","synonyms":["justice system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"criminal record","meaning":"an official history of a person's criminal convictions","translation":"tiền án","example":"A criminal record can make finding employment difficult.","synonyms":["record of offences"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"victim support","meaning":"services that help people affected by crime","translation":"hỗ trợ nạn nhân","example":"Victim support should include legal and psychological assistance.","synonyms":["help for victims"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"violent crime","meaning":"crime involving physical force or threat","translation":"tội phạm bạo lực","example":"Communities are especially concerned about violent crime.","synonyms":["serious violence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Crime & Justice","word":"petty crime","meaning":"relatively minor offences such as small thefts","translation":"tội phạm nhỏ","example":"Better street lighting may reduce some forms of petty crime.","synonyms":["minor crime"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"public spending","meaning":"money spent by government on services and programmes","translation":"chi tiêu công","example":"Public spending on education can produce long-term benefits.","synonyms":["government expenditure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"taxation","meaning":"the system of collecting taxes","translation":"hệ thống thuế","example":"Taxation can be used to fund healthcare and infrastructure.","synonyms":["tax system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"welfare","meaning":"financial and social support provided to people in need","translation":"phúc lợi xã hội","example":"Welfare programmes can protect families during unemployment.","synonyms":["social support"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"regulation","meaning":"an official rule controlling an activity","translation":"quy định","example":"Environmental regulation can limit harmful industrial practices.","synonyms":["official rule"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"legislation","meaning":"laws considered collectively or a new law introduced by government","translation":"pháp luật","example":"New legislation may be needed to protect online privacy.","synonyms":["law"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"government funding","meaning":"money provided by the state for a purpose","translation":"tài trợ của chính phủ","example":"Government funding can keep rural hospitals open.","synonyms":["state funding"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"public sector","meaning":"the part of the economy controlled or funded by government","translation":"khu vực công","example":"Teachers and nurses are important public-sector workers.","synonyms":["state sector"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"private sector","meaning":"businesses and organisations owned by individuals or companies","translation":"khu vực tư","example":"The private sector can contribute investment and innovation.","synonyms":["business sector"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"social policy","meaning":"government action designed to improve social conditions","translation":"chính sách xã hội","example":"Effective social policy should consider vulnerable groups.","synonyms":["welfare policy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"decision-making","meaning":"the process of choosing between possible actions","translation":"quá trình ra quyết định","example":"Public consultation can improve government decision-making.","synonyms":["choice process"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"public interest","meaning":"the well-being or benefit of society as a whole","translation":"lợi ích công cộng","example":"Transport policy should serve the public interest.","synonyms":["common good"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"state support","meaning":"help provided by government","translation":"hỗ trợ của nhà nước","example":"Small businesses may need temporary state support during crises.","synonyms":["government assistance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"local government","meaning":"official administration of a town, city or region","translation":"chính quyền địa phương","example":"Local government is responsible for many everyday services.","synonyms":["municipal authority"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Government & Public Policy","word":"national priority","meaning":"an issue considered especially important for a country","translation":"ưu tiên quốc gia","example":"Affordable healthcare should be treated as a national priority.","synonyms":["major national goal"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"economy","meaning":"the system of producing, trading and using goods and services","translation":"nền kinh tế","example":"A strong economy can create more employment opportunities.","synonyms":["economic system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"economic growth","meaning":"an increase in the value of goods and services produced","translation":"tăng trưởng kinh tế","example":"Economic growth can raise incomes but also increase resource use.","synonyms":["economic expansion"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"income","meaning":"money received from work, business or investments","translation":"thu nhập","example":"Housing costs take up a large share of household income.","synonyms":["earnings"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"income inequality","meaning":"unequal distribution of income across society","translation":"bất bình đẳng thu nhập","example":"Income inequality can limit access to education and healthcare.","synonyms":["earnings gap"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"consumer","meaning":"a person who buys or uses goods and services","translation":"người tiêu dùng","example":"Consumers are increasingly concerned about product sustainability.","synonyms":["buyer"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"consumerism","meaning":"a strong focus on buying and owning goods","translation":"chủ nghĩa tiêu dùng","example":"Consumerism can encourage wasteful spending and production.","synonyms":["material consumption"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"living costs","meaning":"the amount of money needed for everyday life","translation":"chi phí sinh hoạt","example":"Rising living costs place pressure on low-income households.","synonyms":["cost of living"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"inflation","meaning":"a general increase in prices over time","translation":"lạm phát","example":"High inflation reduces the purchasing power of salaries.","synonyms":["rising prices"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"unemployment","meaning":"the state of being without work while seeking a job","translation":"thất nghiệp","example":"Youth unemployment can create long-term social problems.","synonyms":["joblessness"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"financial pressure","meaning":"stress caused by money problems","translation":"áp lực tài chính","example":"High rent can create financial pressure for young workers.","synonyms":["money stress"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"household income","meaning":"the total income received by people in one household","translation":"thu nhập hộ gia đình","example":"Household income strongly affects spending choices.","synonyms":["family earnings"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"standard of living","meaning":"the material comfort available to a person or society","translation":"mức sống","example":"Access to clean water is a basic part of a decent standard of living.","synonyms":["living standard"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"demand","meaning":"the amount of a product or service that people want to buy","translation":"nhu cầu","example":"Demand for affordable housing remains high.","synonyms":["market demand"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Economy & Consumerism","word":"supply","meaning":"the amount of a product or service available","translation":"nguồn cung","example":"Limited housing supply can push prices upward.","synonyms":["availability"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"advertising","meaning":"the activity of promoting products, services or ideas","translation":"quảng cáo","example":"Advertising can shape consumer preferences.","synonyms":["promotion"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"marketing","meaning":"activities used to promote and sell products","translation":"tiếp thị","example":"Digital marketing allows companies to target specific audiences.","synonyms":["promotion strategy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"commercial","meaning":"an advertisement on television, radio or online video","translation":"quảng cáo thương mại","example":"A memorable commercial can increase brand recognition.","synonyms":["advert"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"consumer behaviour","meaning":"the way people choose, buy and use products","translation":"hành vi người tiêu dùng","example":"Social media has changed consumer behaviour.","synonyms":["buying behaviour"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"target market","meaning":"the group of customers a product is intended for","translation":"thị trường mục tiêu","example":"Companies design campaigns for a specific target market.","synonyms":["customer segment"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"advertising campaign","meaning":"a planned series of promotional messages","translation":"chiến dịch quảng cáo","example":"The advertising campaign focused on young adults.","synonyms":["marketing campaign"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"mass communication","meaning":"the sharing of information with large audiences","translation":"truyền thông đại chúng","example":"Television remains an important form of mass communication.","synonyms":["public communication"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"press freedom","meaning":"the right of journalists to report without improper control","translation":"tự do báo chí","example":"Press freedom supports public debate and accountability.","synonyms":["media freedom"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"news coverage","meaning":"the way news organisations report an event or issue","translation":"việc đưa tin","example":"Extensive news coverage can influence public concern.","synonyms":["media reporting"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"public opinion","meaning":"the views held by many people in society","translation":"dư luận","example":"Media stories can affect public opinion about social policies.","synonyms":["popular view"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"media influence","meaning":"the effect that media has on attitudes or behaviour","translation":"ảnh hưởng truyền thông","example":"Media influence is especially strong among frequent users.","synonyms":["media impact"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"celebrity endorsement","meaning":"promotion of a product by a famous person","translation":"quảng cáo nhờ người nổi tiếng","example":"Celebrity endorsement can make products more attractive to teenagers.","synonyms":["famous-person promotion"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"persuasive","meaning":"good at convincing people to believe or do something","translation":"có sức thuyết phục","example":"Advertisements often use persuasive language.","synonyms":["convincing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Media & Advertising","word":"sensational","meaning":"designed to create strong excitement or shock","translation":"giật gân","example":"Sensational headlines may attract clicks but reduce trust.","synonyms":["dramatic"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"globalisation","meaning":"the increasing connection of economies and societies worldwide","translation":"toàn cầu hóa","example":"Globalisation has increased trade and cultural exchange.","synonyms":["global integration"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"immigration","meaning":"the movement of people into another country to live","translation":"nhập cư","example":"Immigration can help countries fill labour shortages.","synonyms":["inward migration"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"emigration","meaning":"the movement of people out of their country to live elsewhere","translation":"di cư ra nước ngoài","example":"High emigration can reduce the number of skilled workers.","synonyms":["outward migration"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"migrant","meaning":"a person who moves to another place for work or life","translation":"người di cư","example":"Migrant workers often contribute to essential industries.","synonyms":["mobile worker"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"international trade","meaning":"the buying and selling of goods and services between countries","translation":"thương mại quốc tế","example":"International trade can give consumers more product choices.","synonyms":["global trade"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"cultural exchange","meaning":"the sharing of ideas, customs and experiences between cultures","translation":"giao lưu văn hóa","example":"Student travel can encourage cultural exchange.","synonyms":["cross-cultural exchange"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"multicultural society","meaning":"a society containing people from many cultural backgrounds","translation":"xã hội đa văn hóa","example":"A multicultural society may benefit from diverse languages and traditions.","synonyms":["diverse society"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"border","meaning":"the official line separating two countries","translation":"biên giới","example":"Border policies affect tourism, trade and migration.","synonyms":["boundary"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"overseas","meaning":"in or to another country, especially across the sea","translation":"ở nước ngoài","example":"Many graduates seek employment overseas.","synonyms":["abroad"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"global market","meaning":"the international system for buying and selling goods and services","translation":"thị trường toàn cầu","example":"Small firms can now reach the global market online.","synonyms":["world market"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"foreign investment","meaning":"money invested in a country by overseas businesses or individuals","translation":"đầu tư nước ngoài","example":"Foreign investment can create jobs and infrastructure.","synonyms":["overseas investment"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"brain drain","meaning":"the loss of skilled people who move to work abroad","translation":"chảy máu chất xám","example":"Brain drain can weaken public services in poorer countries.","synonyms":["skills loss"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"integration","meaning":"the process of becoming part of a wider society or system","translation":"hội nhập","example":"Language education can support migrant integration.","synonyms":["inclusion"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Globalisation & Migration","word":"cultural diversity","meaning":"the presence of many different cultures in one place","translation":"đa dạng văn hóa","example":"Cultural diversity can enrich urban life.","synonyms":["cultural variety"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"cultural heritage","meaning":"traditions, places and objects inherited from the past","translation":"di sản văn hóa","example":"Protecting cultural heritage can support both identity and tourism.","synonyms":["heritage"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"historic site","meaning":"a place important because of its history","translation":"di tích lịch sử","example":"Historic sites require careful maintenance.","synonyms":["heritage site"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"preserve","meaning":"to keep something important in its original or good condition","translation":"bảo tồn","example":"Museums help preserve objects from the past.","synonyms":["protect"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"museum","meaning":"a place where objects of historical, scientific or artistic value are displayed","translation":"bảo tàng","example":"Museums can make history accessible to the public.","synonyms":["gallery"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"traditional values","meaning":"long-standing beliefs about acceptable behaviour and society","translation":"giá trị truyền thống","example":"Traditional values may change as societies modernise.","synonyms":["conventional values"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"local customs","meaning":"traditional practices of a particular place","translation":"phong tục địa phương","example":"Visitors should respect local customs.","synonyms":["regional traditions"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"generation gap","meaning":"differences in attitudes between younger and older generations","translation":"khoảng cách thế hệ","example":"Technology can widen the generation gap in some families.","synonyms":["age divide"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"modernisation","meaning":"the process of becoming more modern","translation":"hiện đại hóa","example":"Modernisation can improve services while changing traditional lifestyles.","synonyms":["development"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"cultural influence","meaning":"the effect one culture has on another","translation":"ảnh hưởng văn hóa","example":"Global media increases cultural influence across borders.","synonyms":["cultural impact"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"indigenous","meaning":"originating naturally from a particular place or people","translation":"bản địa","example":"Indigenous languages may need support to survive.","synonyms":["native"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"language preservation","meaning":"efforts to keep a language in active use","translation":"bảo tồn ngôn ngữ","example":"Schools can contribute to language preservation.","synonyms":["language protection"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"national identity","meaning":"a shared sense of belonging to a nation","translation":"bản sắc quốc gia","example":"Sporting events can strengthen national identity.","synonyms":["national belonging"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"cultural tourism","meaning":"tourism based on history, arts and local traditions","translation":"du lịch văn hóa","example":"Cultural tourism can create income for historic towns.","synonyms":["heritage tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Culture & Heritage","word":"historical value","meaning":"importance that something has because of its connection with the past","translation":"giá trị lịch sử","example":"Old buildings may have historical value even when they are not practical.","synonyms":["heritage importance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"science","meaning":"systematic study of the natural and physical world","translation":"khoa học","example":"Science can improve health, energy and communication.","synonyms":["scientific study"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"scientific research","meaning":"careful investigation designed to produce new knowledge","translation":"nghiên cứu khoa học","example":"Scientific research often requires long-term investment.","synonyms":["research"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"innovation","meaning":"a new idea, method or product that improves something","translation":"đổi mới","example":"Innovation can help businesses remain competitive.","synonyms":["new development"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"invention","meaning":"a newly created device, process or idea","translation":"phát minh","example":"Some inventions completely change everyday life.","synonyms":["new creation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"experiment","meaning":"a controlled test used to discover or prove something","translation":"thí nghiệm","example":"A scientific experiment should be designed to produce reliable evidence.","synonyms":["test"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research funding","meaning":"money provided to support research","translation":"kinh phí nghiên cứu","example":"Research funding is essential for expensive medical studies.","synonyms":["research finance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"scientific evidence","meaning":"information from research that supports or challenges a claim","translation":"bằng chứng khoa học","example":"Public policy should consider strong scientific evidence.","synonyms":["research evidence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"breakthrough","meaning":"an important discovery or major advance","translation":"bước đột phá","example":"A medical breakthrough can save many lives.","synonyms":["major advance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"laboratory","meaning":"a place equipped for scientific experiments","translation":"phòng thí nghiệm","example":"The laboratory follows strict safety procedures.","synonyms":["lab"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"researcher","meaning":"a person who carries out systematic investigation","translation":"nhà nghiên cứu","example":"Researchers must report their methods clearly.","synonyms":["scientist"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"technological development","meaning":"the creation and improvement of technology","translation":"phát triển công nghệ","example":"Technological development can create new industries.","synonyms":["technology progress"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"medical research","meaning":"research aimed at improving health and treatment","translation":"nghiên cứu y khoa","example":"Medical research has increased survival rates for many diseases.","synonyms":["health research"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"space research","meaning":"scientific study related to space and astronomy","translation":"nghiên cứu vũ trụ","example":"Space research can produce technologies with uses on Earth.","synonyms":["space science"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research findings","meaning":"the results produced by a study","translation":"kết quả nghiên cứu","example":"Research findings should be communicated accurately.","synonyms":["study results"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"birth rate","meaning":"the number of births in a population over a period","translation":"tỷ lệ sinh","example":"The birth rate has fallen in many developed countries.","synonyms":["fertility rate"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"ageing population","meaning":"a population with a growing share of older people","translation":"dân số già","example":"An ageing population increases demand for healthcare.","synonyms":["older population"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"nuclear family","meaning":"a family consisting mainly of parents and their children","translation":"gia đình hạt nhân","example":"Th