},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"ageing society","meaning":"a society in which older people form an increasing share","translation":"xã hội già hóa","example":"An ageing society may need changes to pension policy.","synonyms":["older society"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"population growth","meaning":"an increase in the number of people living in a place","translation":"tăng dân số","example":"Rapid population growth can strain public infrastructure.","synonyms":["demographic growth"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"life stage","meaning":"a particular period in a person's life","translation":"giai đoạn cuộc đời","example":"Housing needs change at different life stages.","synonyms":["stage of life"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"elderly care","meaning":"support and services provided to older people","translation":"chăm sóc người cao tuổi","example":"Governments must plan for rising elderly-care needs.","synonyms":["senior care"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourist attraction","meaning":"a place or activity that visitors want to see","translation":"điểm thu hút khách du lịch","example":"A famous tourist attraction can bring income to a region.","synonyms":["visitor attraction"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"peak season","meaning":"the busiest period for tourism or business","translation":"mùa cao điểm","example":"Hotel prices often rise during peak season.","synonyms":["high season"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"local economy","meaning":"the economic activity of a town or region","translation":"kinh tế địa phương","example":"Tourism can support the local economy through jobs and spending.","synonyms":["regional economy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"sustainable tourism","meaning":"tourism designed to limit environmental and social harm","translation":"du lịch bền vững","example":"Sustainable tourism should protect natural and cultural resources.","synonyms":["responsible tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"package holiday","meaning":"a holiday sold as one deal including travel and accommodation","translation":"tour trọn gói","example":"Package holidays can make international travel simpler.","synonyms":["package tour"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourist industry","meaning":"businesses that provide services to visitors","translation":"ngành du lịch","example":"The tourist industry employs large numbers of seasonal workers.","synonyms":["tourism sector"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"visitor numbers","meaning":"the number of people visiting a place","translation":"lượng khách tham quan","example":"High visitor numbers can damage fragile natural sites.","synonyms":["tourist numbers"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism revenue","meaning":"money earned from tourism","translation":"doanh thu du lịch","example":"Tourism revenue can fund local infrastructure.","synonyms":["visitor income"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"seasonal jobs","meaning":"jobs available only during certain parts of the year","translation":"việc làm thời vụ","example":"Coastal resorts often depend on seasonal jobs.","synonyms":["temporary tourism work"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourist behaviour","meaning":"the way visitors act while travelling","translation":"hành vi du khách","example":"Responsible tourist behaviour can reduce damage to local communities.","synonyms":["visitor conduct"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"local residents","meaning":"people who live permanently in a particular area","translation":"cư dân địa phương","example":"Local residents should benefit from tourism development.","synonyms":["local people"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"overcrowded destination","meaning":"a tourist place receiving too many visitors","translation":"điểm đến quá tải","example":"An overcrowded destination may need limits on daily visitors.","synonyms":["overtouristed place"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism management","meaning":"planning and controlling tourism development","translation":"quản lý du lịch","example":"Good tourism management balances income with environmental protection.","synonyms":["destination management"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"agriculture","meaning":"the activity of farming crops and animals","translation":"nông nghiệp","example":"Agriculture remains a major source of employment in many regions.","synonyms":["farming"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"farmer","meaning":"a person who grows crops or keeps animals","translation":"nông dân","example":"Farmers need reliable access to water and markets.","synonyms":["agricultural worker"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"crop","meaning":"a plant grown on a large scale for food or other use","translation":"cây trồng","example":"Drought can reduce crop yields.","synonyms":["farm produce"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"farmland","meaning":"land used for growing crops or keeping animals","translation":"đất nông nghiệp","example":"Urban expansion can reduce available farmland.","synonyms":["agricultural land"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food production","meaning":"the process of growing, processing and preparing food","translation":"sản xuất thực phẩm","example":"Climate change may threaten food production in dry regions.","synonyms":["food output"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food supply","meaning":"the amount and availability of food for a population","translation":"nguồn cung thực phẩm","example":"Reliable transport is important for the national food supply.","synonyms":["food availability"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"organic food","meaning":"food produced without many synthetic chemicals","translation":"thực phẩm hữu cơ","example":"Organic food is often more expensive than conventional alternatives.","synonyms":["organic produce"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"pesticide","meaning":"a chemical used to kill insects or other organisms that damage crops","translation":"thuốc trừ sâu","example":"Excessive pesticide use can harm wildlife and water quality.","synonyms":["crop chemical"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"fertiliser","meaning":"a substance added to soil to help plants grow","translation":"phân bón","example":"Farmers use fertiliser to improve crop growth.","synonyms":["plant nutrient"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food waste","meaning":"edible food that is thrown away or lost","translation":"lãng phí thực phẩm","example":"Reducing food waste can lower both costs and environmental damage.","synonyms":["wasted food"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"processed food","meaning":"food changed from its natural state through industrial methods","translation":"thực phẩm chế biến","example":"Highly processed food often contains large amounts of salt or sugar.","synonyms":["manufactured food"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food safety","meaning":"practices that keep food free from harmful contamination","translation":"an toàn thực phẩm","example":"Strong food-safety rules protect public health.","synonyms":["safe food handling"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"farming methods","meaning":"techniques used to grow crops or raise animals","translation":"phương pháp canh tác","example":"Modern farming methods can increase output but also affect ecosystems.","synonyms":["agricultural techniques"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"gender equality","meaning":"equal rights, opportunities and treatment regardless of gender","translation":"bình đẳng giới","example":"Gender equality can increase economic participation.","synonyms":["equality between genders"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"equal opportunity","meaning":"the same chance to succeed without unfair barriers","translation":"cơ hội bình đẳng","example":"Recruitment should provide equal opportunity to qualified applicants.","synonyms":["fair chance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"discrimination","meaning":"unfair treatment based on personal characteristics","translation":"phân biệt đối xử","example":"Workplace discrimination can limit career progression.","synonyms":["unfair treatment"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"gender roles","meaning":"social expectations about how men and women should behave","translation":"vai trò giới","example":"Traditional gender roles are changing in many societies.","synonyms":["social roles"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"equal pay","meaning":"the principle of paying people equally for comparable work","translation":"trả lương bình đẳng","example":"Equal pay remains an important workplace issue.","synonyms":["pay equality"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"workplace equality","meaning":"fair treatment and opportunity at work","translation":"bình đẳng nơi làm việc","example":"Workplace equality can improve staff morale and retention.","synonyms":["employment equality"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"women's rights","meaning":"legal and social rights held by women","translation":"quyền phụ nữ","example":"Education has played a major role in expanding women's rights.","synonyms":["female rights"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"male-dominated","meaning":"mainly controlled or occupied by men","translation":"do nam giới chiếm đa số","example":"Some engineering fields remain male-dominated.","synonyms":["mostly male"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"female participation","meaning":"the involvement of women in an activity or sector","translation":"sự tham gia của phụ nữ","example":"Affordable childcare can increase female participation in employment.","synonyms":["women's participation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"career break","meaning":"a period away from employment, often for family or personal reasons","translation":"thời gian tạm nghỉ sự nghiệp","example":"A long career break can make returning to work more difficult.","synonyms":["employment break"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"childcare duties","meaning":"responsibilities involved in caring for children","translation":"trách nhiệm chăm sóc trẻ","example":"Childcare duties are increasingly shared by both parents.","synonyms":["care responsibilities"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"social expectations","meaning":"ideas about how people are expected to behave","translation":"kỳ vọng xã hội","example":"Social expectations can influence career choices.","synonyms":["social norms"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"representation","meaning":"the presence of people from a group in positions or institutions","translation":"sự đại diện","example":"Greater representation of women can broaden decision-making.","synonyms":["presence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"professional sport","meaning":"sport played as paid employment","translation":"thể thao chuyên nghiệp","example":"Professional sport attracts large audiences and sponsorship.","synonyms":["elite sport"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"spectator","meaning":"a person who watches a sports event","translation":"khán giả thể thao","example":"Spectators contribute to revenue through tickets and merchandise.","synonyms":["viewer"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports facilities","meaning":"places and equipment provided for physical activity","translation":"cơ sở thể thao","example":"Public sports facilities can encourage healthier lifestyles.","synonyms":["sport amenities"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sportsmanship","meaning":"fair and respectful behaviour in sport","translation":"tinh thần thể thao","example":"Schools can use competitions to teach sportsmanship.","synonyms":["fair play"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"physical education","meaning":"school lessons focused on exercise and sport","translation":"giáo dục thể chất","example":"Physical education helps children develop active habits.","synonyms":["PE"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"competitive sport","meaning":"sport in which individuals or teams compete to win","translation":"thể thao cạnh tranh","example":"Competitive sport can build discipline but also create pressure.","synonyms":["organised competition"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"team spirit","meaning":"a feeling of cooperation and loyalty within a team","translation":"tinh thần đồng đội","example":"Team sports can strengthen team spirit among students.","synonyms":["group unity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports funding","meaning":"money provided to support sport","translation":"kinh phí thể thao","example":"Sports funding should include community as well as elite programmes.","synonyms":["sport finance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"public participation","meaning":"involvement of ordinary people in an activity","translation":"sự tham gia của công chúng","example":"Low-cost programmes can increase public participation in sport.","synonyms":["community involvement"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"elite athlete","meaning":"a sportsperson competing at a very high level","translation":"vận động viên đỉnh cao","example":"Elite athletes often require specialist coaching and medical support.","synonyms":["top athlete"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sporting event","meaning":"an organised competition or match","translation":"sự kiện thể thao","example":"A major sporting event can attract international visitors.","synonyms":["sports event"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"exercise habits","meaning":"regular patterns of physical activity","translation":"thói quen vận động","example":"Exercise habits formed in childhood may continue into adulthood.","synonyms":["activity habits"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"inactive lifestyle","meaning":"a lifestyle involving too little physical movement","translation":"lối sống thiếu vận động","example":"An inactive lifestyle contributes to obesity and poor fitness.","synonyms":["low-activity lifestyle"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"arts funding","meaning":"money provided to support artistic activities","translation":"kinh phí nghệ thuật","example":"Arts funding can help theatres and museums serve wider audiences.","synonyms":["cultural finance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"cultural institution","meaning":"an organisation such as a museum, theatre or gallery","translation":"tổ chức văn hóa","example":"Cultural institutions preserve and present shared heritage.","synonyms":["arts institution"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"performing arts","meaning":"creative activities performed for audiences, such as music or theatre","translation":"nghệ thuật biểu diễn","example":"Performing arts can create jobs and enrich city life.","synonyms":["stage arts"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"visual arts","meaning":"art forms mainly seen, such as painting and sculpture","translation":"nghệ thuật thị giác","example":"Public galleries make visual arts accessible to more people.","synonyms":["fine arts"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"public funding","meaning":"money provided by government for a public purpose","translation":"tài trợ công","example":"Public funding can support arts that are not commercially profitable.","synonyms":["state funding"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"creative industry","meaning":"business sectors based on creativity, culture and intellectual work","translation":"ngành công nghiệp sáng tạo","example":"The creative industry contributes to employment and tourism.","synonyms":["creative sector"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"artist","meaning":"a person who creates art","translation":"nghệ sĩ","example":"Artists often need affordable spaces in large cities.","synonyms":["creator"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"exhibition","meaning":"a public display of art or other objects","translation":"triển lãm","example":"The museum organised an exhibition about local history.","synonyms":["display"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"theatre","meaning":"a place or activity involving live dramatic performance","translation":"nhà hát, sân khấu","example":"Theatre can introduce audiences to difficult social issues.","synonyms":["drama"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"cultural programme","meaning":"an organised set of activities related to arts or culture","translation":"chương trình văn hóa","example":"A cultural programme can increase community participation.","synonyms":["arts programme"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"artistic expression","meaning":"the communication of ideas or emotions through art","translation":"biểu đạt nghệ thuật","example":"Artistic expression should be protected even when it is controversial.","synonyms":["creative expression"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"entertainment industry","meaning":"businesses that produce films, music, games and similar content","translation":"ngành giải trí","example":"The entertainment industry increasingly depends on digital platforms.","synonyms":["media industry"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"public value","meaning":"benefit created for society rather than private profit","translation":"giá trị công","example":"Free museums can create public value through education.","synonyms":["social value"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"elderly","meaning":"old or relating to older people","translation":"cao tuổi","example":"Elderly people may need accessible transport and healthcare.","synonyms":["older"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"retirement","meaning":"the period after a person stops regular paid work","translation":"nghỉ hưu","example":"People are living longer after retirement than in the past.","synonyms":["post-work life"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"pension","meaning":"regular money paid to a person after retirement","translation":"lương hưu","example":"Governments must ensure that pension systems remain affordable.","synonyms":["retirement income"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"retirement age","meaning":"the age at which people usually stop working","translation":"tuổi nghỉ hưu","example":"Some countries are raising the retirement age.","synonyms":["pension age"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"senior citizen","meaning":"a polite term for an older adult","translation":"người cao tuổi","example":"Senior citizens can contribute through volunteering and part-time work.","synonyms":["older adult"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"elderly population","meaning":"the older people within a population","translation":"dân số cao tuổi","example":"The elderly population is growing in many developed economies.","synonyms":["older population"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"care home","meaning":"a residential place that provides care for older or disabled people","translation":"nhà dưỡng lão","example":"Care homes require well-trained staff.","synonyms":["residential care"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"healthcare costs","meaning":"money spent on medical services and treatment","translation":"chi phí y tế","example":"An ageing population can increase national healthcare costs.","synonyms":["medical expenses"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"social isolation","meaning":"a lack of regular social contact with other people","translation":"cô lập xã hội","example":"Social isolation is a serious risk for some older adults.","synonyms":["loneliness"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"active ageing","meaning":"remaining healthy and involved in society as one grows older","translation":"già hóa năng động","example":"Community exercise programmes can support active ageing.","synonyms":["healthy ageing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"family care","meaning":"care provided by relatives rather than formal services","translation":"chăm sóc trong gia đình","example":"Family care remains important in many cultures.","synonyms":["informal care"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"older workforce","meaning":"employees who are relatively advanced in age","translation":"lực lượng lao động lớn tuổi","example":"An older workforce may have valuable experience but different training needs.","synonyms":["ageing workforce"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"age discrimination","meaning":"unfair treatment because of a person's age","translation":"phân biệt tuổi tác","example":"Age discrimination can prevent capable older workers from finding jobs.","synonyms":["ageism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"second language","meaning":"a language learned in addition to one's first language","translation":"ngôn ngữ thứ hai","example":"Learning a second language can improve study and job opportunities.","synonyms":["additional language"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"foreign language","meaning":"a language from another country","translation":"ngoại ngữ","example":"Many schools introduce a foreign language in primary education.","synonyms":["other language"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"bilingual","meaning":"able to use two languages","translation":"song ngữ","example":"Bilingual children may switch languages depending on context.","synonyms":["two-language"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"fluency","meaning":"the ability to use a language smoothly and easily","translation":"sự lưu loát","example":"Regular conversation practice can improve fluency.","synonyms":["smooth speech"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"pronunciation","meaning":"the way words are spoken","translation":"phát âm","example":"Clear pronunciation helps listeners understand unfamiliar words.","synonyms":["speech sound"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"vocabulary","meaning":"the words known and used by a person","translation":"từ vựng","example":"Reading widely is an effective way to build vocabulary.","synonyms":["word knowledge"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"grammar","meaning":"the rules for forming sentences in a language","translation":"ngữ pháp","example":"Accurate grammar is important in formal writing.","synonyms":["language rules"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language barrier","meaning":"difficulty communicating because people do not share a language","translation":"rào cản ngôn ngữ","example":"A language barrier can limit migrants' access to services.","synonyms":["communication barrier"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language skills","meaning":"abilities in reading, writing, listening and speaking","translation":"kỹ năng ngôn ngữ","example":"Employers increasingly value strong language skills.","synonyms":["linguistic skills"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"native speaker","meaning":"a person who learned a language from early childhood","translation":"người bản ngữ","example":"Learners do not need to sound exactly like a native speaker.","synonyms":["first-language speaker"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language course","meaning":"a planned programme for learning a language","translation":"khóa học ngôn ngữ","example":"An intensive language course can prepare students for overseas study.","synonyms":["language class"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"immersion","meaning":"learning a language through extensive exposure and use","translation":"học theo môi trường nhập vai","example":"Immersion can accelerate language learning when learners use the language daily.","synonyms":["full exposure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"communication skills","meaning":"abilities used to exchange ideas clearly with others","translation":"kỹ năng giao tiếp","example":"Communication skills are important in both study and employment.","synonyms":["interpersonal skills"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"artificial intelligence","meaning":"computer systems designed to perform tasks that normally require human intelligence","translation":"trí tuệ nhân tạo","example":"Artificial intelligence is transforming education, healthcare and employment.","synonyms":["AI"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"machine learning","meaning":"a branch of AI in which systems learn patterns from data","translation":"học máy","example":"Machine learning can improve predictions but depends heavily on data quality.","synonyms":["ML"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"generative AI","meaning":"AI systems that create new text, images, audio or code","translation":"AI tạo sinh","example":"Generative AI raises questions about authorship and academic integrity.","synonyms":["generative technology"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"algorithmic decision-making","meaning":"the use of algorithms to make or support important decisions","translation":"ra quyết định bằng thuật toán","example":"Algorithmic decision-making should be transparent when it affects employment or credit.","synonyms":["automated decision-making"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"autonomous system","meaning":"a system able to operate with limited direct human control","translation":"hệ thống tự chủ","example":"Autonomous systems may improve efficiency in transport and manufacturing.","synonyms":["self-operating system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"labour displacement","meaning":"the loss or movement of jobs because technology replaces certain tasks","translation":"dịch chuyển lao động","example":"Automation may cause labour displacement in routine occupations.","synonyms":["job displacement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"human oversight","meaning":"human monitoring and control of automated systems","translation":"sự giám sát của con người","example":"High-risk AI applications should remain under meaningful human oversight.","synonyms":["human supervision"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"productivity gains","meaning":"increases in output achieved with the same or fewer resources","translation":"mức tăng năng suất","example":"AI may generate productivity gains by automating repetitive work.","synonyms":["efficiency gains"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"technological unemployment","meaning":"job loss caused by technological change","translation":"thất nghiệp do công nghệ","example":"Technological unemployment may require stronger retraining policies.","synonyms":["automation-related job loss"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"reskilling","meaning":"training workers to perform a different type of job","translation":"đào tạo lại kỹ năng","example":"Governments may need to support reskilling for workers affected by automation.","synonyms":["retraining"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"upskilling","meaning":"improving existing skills so workers can perform more advanced tasks","translation":"nâng cao kỹ năng","example":"Continuous upskilling can help employees adapt to new technologies.","synonyms":["skill upgrading"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"human-machine collaboration","meaning":"work in which people and intelligent systems complement each other","translation":"hợp tác người-máy","example":"Human-machine collaboration can combine human judgement with computational speed.","synonyms":["human-AI teamwork"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"algorithmic bias","meaning":"systematic unfairness produced by an algorithm","translation":"thiên lệch thuật toán","example":"Poor training data can lead to algorithmic bias in hiring systems.","synonyms":["automated bias"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"automation anxiety","meaning":"fear or concern about technology replacing human work","translation":"lo âu về tự động hóa","example":"Automation anxiety is common when employees lack information about future roles.","synonyms":["technology-related job fear"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate mitigation","meaning":"action taken to reduce the causes of climate change","translation":"giảm nhẹ biến đổi khí hậu","example":"Climate mitigation requires lower emissions across transport, energy and industry.","synonyms":["emissions reduction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate adaptation","meaning":"adjustments that reduce harm from present or future climate effects","translation":"thích ứng với biến đổi khí hậu","example":"Coastal cities need climate adaptation measures to manage rising sea levels.","synonyms":["adaptation measures"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"net-zero target","meaning":"a goal of balancing greenhouse-gas emissions with equivalent removals","translation":"mục tiêu phát thải ròng bằng 0","example":"A credible net-zero target should include clear intermediate milestones.","synonyms":["carbon-neutral target"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"carbon footprint","meaning":"the total greenhouse-gas emissions associated with a person, product or activity","translation":"dấu chân carbon","example":"Consumers can reduce their carbon footprint by using less energy and flying less.","synonyms":["emissions footprint"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"carbon pricing","meaning":"a policy that assigns a financial cost to carbon emissions","translation":"định giá carbon","example":"Carbon pricing can encourage businesses to adopt cleaner technology.","synonyms":["emissions pricing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"ecosystem","meaning":"a community of living organisms interacting with their physical environment","translation":"hệ sinh thái","example":"Wetland ecosystems provide flood protection and wildlife habitats.","synonyms":["ecological system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"habitat destruction","meaning":"the damage or removal of natural places where species live","translation":"phá hủy môi trường sống","example":"Agricultural expansion can accelerate habitat destruction.","synonyms":["habitat loss"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"species extinction","meaning":"the permanent disappearance of a species","translation":"sự tuyệt chủng của loài","example":"Habitat loss and climate change increase the risk of species extinction.","synonyms":["extinction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"biodiversity loss","meaning":"a decline in the variety of living species and ecosystems","translation":"suy giảm đa dạng sinh học","example":"Biodiversity loss can weaken ecosystem resilience.","synonyms":["ecological decline"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate resilience","meaning":"the ability to prepare for and recover from climate-related shocks","translation":"khả năng chống chịu khí hậu","example":"Climate resilience should be built into infrastructure planning.","synonyms":["resilience to climate impacts"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"environmental degradation","meaning":"the deterioration of the natural environment","translation":"suy thoái môi trường","example":"Poor land management can cause long-term environmental degradation.","synonyms":["ecological damage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"protected area","meaning":"land or water legally managed for conservation","translation":"khu bảo tồn","example":"Protected areas can preserve habitats when enforcement is effective.","synonyms":["conservation zone"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"ecological balance","meaning":"a relatively stable relationship among organisms and their environment","translation":"cân bằng sinh thái","example":"Removing one species can disturb ecological balance.","synonyms":["ecosystem balance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"conservation policy","meaning":"an official strategy for protecting species, habitats and natural resources","translation":"chính sách bảo tồn","example":"Conservation policy should combine habitat protection with local livelihoods.","synonyms":["environmental protection policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy transition","meaning":"the shift from high-carbon energy systems toward cleaner sources","translation":"chuyển dịch năng lượng","example":"The energy transition requires investment, regulation and new infrastructure.","synonyms":["clean-energy transition"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"decarbonisation","meaning":"the process of reducing carbon emissions from an economy or activity","translation":"khử carbon","example":"Industrial decarbonisation is difficult in sectors such as steel and cement.","synonyms":["carbon reduction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"solar power","meaning":"electricity or heat produced from sunlight","translation":"năng lượng mặt trời","example":"Solar power has become cheaper in many markets.","synonyms":["solar energy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"wind power","meaning":"energy produced by wind turbines","translation":"năng lượng gió","example":"Offshore wind power can provide large amounts of low-carbon electricity.","synonyms":["wind energy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy storage","meaning":"technology used to store energy for later use","translation":"lưu trữ năng lượng","example":"Energy storage helps balance variable renewable generation.","synonyms":["power storage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"electricity grid","meaning":"the network that carries electricity from producers to users","translation":"lưới điện","example":"A modern electricity grid must handle more distributed renewable power.","synonyms":["power grid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"clean-energy investment","meaning":"money invested in low-carbon and renewable energy systems","translation":"đầu tư năng lượng sạch","example":"Clean-energy investment can create jobs while reducing emissions.","synonyms":["green-energy investment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy security","meaning":"reliable access to sufficient and affordable energy","translation":"an ninh năng lượng","example":"Countries diversify energy sources to strengthen energy security.","synonyms":["secure energy supply"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"nuclear power","meaning":"energy produced through controlled nuclear reactions","translation":"năng lượng hạt nhân","example":"Nuclear power provides low-carbon electricity but raises cost and waste concerns.","synonyms":["nuclear energy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"renewable capacity","meaning":"the maximum amount of renewable power a system can produce","translation":"công suất năng lượng tái tạo","example":"Many countries are rapidly expanding renewable capacity.","synonyms":["renewable generation capacity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy mix","meaning":"the combination of energy sources used by a country or system","translation":"cơ cấu năng lượng","example":"A diversified energy mix can reduce dependence on imported fuel.","synonyms":["energy portfolio"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"fossil-fuel subsidy","meaning":"government financial support that lowers the cost of fossil fuels","translation":"trợ cấp nhiên liệu hóa thạch","example":"Removing fossil-fuel subsidies can be politically difficult.","synonyms":["fuel subsidy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"electrification","meaning":"the replacement of fossil-fuel technologies with electricity-based alternatives","translation":"điện khí hóa","example":"Transport electrification can cut urban air pollution.","synonyms":["switch to electricity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"low-carbon technology","meaning":"technology designed to produce relatively low greenhouse-gas emissions","translation":"công nghệ carbon thấp","example":"Low-carbon technology is central to long-term climate targets.","synonyms":["clean technology"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"governance","meaning":"the systems and processes used to direct a country or organisation","translation":"quản trị","example":"Good governance depends on effective institutions and public trust.","synonyms":["administration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"accountability","meaning":"the duty to explain decisions and accept responsibility for them","translation":"trách nhiệm giải trình","example":"Independent oversight can strengthen government accountability.","synonyms":["answerability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"transparency","meaning":"openness about decisions, information and processes","translation":"minh bạch","example":"Budget transparency makes it easier for citizens to evaluate public spending.","synonyms":["openness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"civic engagement","meaning":"participation in activities intended to improve public or community life","translation":"tham gia công dân","example":"Civic engagement can increase trust between residents and local authorities.","synonyms":["citizen participation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"public consultation","meaning":"a process in which authorities seek citizens' views before making decisions","translation":"tham vấn công chúng","example":"Public consultation can reveal problems that planners may overlook.","synonyms":["community consultation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"democratic participation","meaning":"involvement in elections, debate and other democratic processes","translation":"tham gia dân chủ","example":"Education may encourage greater democratic participation.","synonyms":["political participation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"institutional trust","meaning":"confidence that public institutions will act competently and fairly","translation":"niềm tin vào thể chế","example":"Corruption can seriously weaken institutional trust.","synonyms":["trust in institutions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"policy implementation","meaning":"the process of putting an official policy into practice","translation":"thực thi chính sách","example":"Strong policy implementation is as important as good policy design.","synonyms":["policy execution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"regulatory framework","meaning":"the overall system of rules governing an activity","translation":"khung pháp lý","example":"A clear regulatory framework can encourage responsible innovation.","synonyms":["regulatory system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"stakeholder","meaning":"a person or group affected by or interested in a decision","translation":"bên liên quan","example":"Major infrastructure projects should involve local stakeholders.","synonyms":["interested party"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"civic duty","meaning":"a responsibility associated with being a member of society","translation":"nghĩa vụ công dân","example":"Voting is often described as a civic duty.","synonyms":["citizen responsibility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"rule of law","meaning":"the principle that everyone, including government, is subject to law","translation":"pháp quyền","example":"The rule of law is essential for stable institutions.","synonyms":["legal equality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"decentralisation","meaning":"the transfer of power from central government to lower levels","translation":"phân quyền","example":"Decentralisation can make some services more responsive to local needs.","synonyms":["devolution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"evidence-based policy","meaning":"policy designed using reliable research and data","translation":"chính sách dựa trên bằng chứng","example":"Evidence-based policy can reduce the influence of short-term political pressure.","synonyms":["research-informed policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"wealth inequality","meaning":"unequal ownership of money, property and other assets","translation":"bất bình đẳng tài sản","example":"Extreme wealth inequality can reduce social mobility.","synonyms":["asset inequality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"social mobility","meaning":"the ability of people to move between social or economic levels","translation":"dịch chuyển xã hội","example":"Affordable education can improve social mobility.","synonyms":["economic mobility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"progressive taxation","meaning":"a tax system in which higher earners pay a larger share of income","translation":"thuế lũy tiến","example":"Progressive taxation can help fund public services and redistribution.","synonyms":["graduated taxation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"minimum wage","meaning":"the lowest legal amount employers may pay workers","translation":"mức lương tối thiểu","example":"A higher minimum wage can raise incomes but may increase labour costs.","synonyms":["wage floor"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"poverty line","meaning":"an income threshold used to identify people living in poverty","translation":"ngưỡng nghèo","example":"Families below the poverty line may qualify for additional support.","synonyms":["poverty threshold"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"wealth distribution","meaning":"the way assets and wealth are shared across a population","translation":"phân bổ tài sản","example":"Tax and housing policy can influence wealth distribution.","synonyms":["distribution of assets"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"social safety net","meaning":"programmes that protect people from severe financial hardship","translation":"mạng lưới an sinh xã hội","example":"A strong social safety net can reduce the effects of unemployment.","synonyms":["welfare safety net"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"fiscal policy","meaning":"government decisions about taxation and public spending","translation":"chính sách tài khóa","example":"Fiscal policy can stimulate demand during an economic downturn.","synonyms":["budgetary policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"monetary policy","meaning":"central-bank actions affecting interest rates and money supply","translation":"chính sách tiền tệ","example":"Monetary policy is often used to control inflation.","synonyms":["central-bank policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"economic mobility","meaning":"the ability to improve one's economic position over time","translation":"dịch chuyển kinh tế","example":"Education and housing costs influence economic mobility.","synonyms":["income mobility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"disposable income","meaning":"money left after taxes for spending or saving","translation":"thu nhập khả dụng","example":"Rising energy bills reduce household disposable income.","synonyms":["after-tax income"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"purchasing power","meaning":"the amount of goods and services money can buy","translation":"sức mua","example":"Inflation lowers the purchasing power of fixed incomes.","synonyms":["buying power"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"labour income","meaning":"money earned from employment rather than investments","translation":"thu nhập từ lao động","example":"Labour income has not risen equally across all sectors.","synonyms":["earned income"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"wealth gap","meaning":"the difference in wealth between richer and poorer groups","translation":"khoảng cách giàu nghèo","example":"High property prices can widen the wealth gap between generations.","synonyms":["asset gap"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"labour market","meaning":"the system in which workers and employers exchange labour for pay","translation":"thị trường lao động","example":"Technological change is reshaping the labour market.","synonyms":["job market"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"gig economy","meaning":"a labour market based on short-term tasks and independent work","translation":"nền kinh tế việc làm ngắn hạn","example":"The gig economy offers flexibility but often provides limited security.","synonyms":["platform work"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"job displacement","meaning":"the loss of jobs because of economic or technological change","translation":"mất việc do thay đổi cơ cấu","example":"Automation may cause job displacement in routine occupations.","synonyms":["employment displacement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"skills mismatch","meaning":"a gap between workers' skills and those required by employers","translation":"lệch pha kỹ năng","example":"Rapid technological change can create a serious skills mismatch.","synonyms":["skill gap"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"labour shortage","meaning":"a situation in which employers cannot find enough suitable workers","translation":"thiếu lao động","example":"Ageing populations are contributing to labour shortages in some sectors.","synonyms":["worker shortage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"workforce participation","meaning":"the share or involvement of people taking part in paid work","translation":"tỷ lệ tham gia lực lượng lao động","example":"Affordable childcare can increase workforce participation.","synonyms":["labour-force participation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"precarious employment","meaning":"work that is insecure, unstable or poorly protected","translation":"việc làm bấp bênh","example":"Precarious employment can make long-term financial planning difficult.","synonyms":["insecure work"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"transferable skills","meaning":"abilities useful across different jobs and industries","translation":"kỹ năng chuyển đổi","example":"Communication and problem-solving are valuable transferable skills.","synonyms":["portable skills"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"lifelong employability","meaning":"the capacity to remain capable of finding work throughout one's career","translation":"khả năng duy trì việc làm lâu dài","example":"Continuous learning supports lifelong employability.","synonyms":["career adaptability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"occupational mobility","meaning":"the ability to move between jobs or professions","translation":"dịch chuyển nghề nghiệp","example":"Retraining can improve occupational mobility after industry decline.","synonyms":["career mobility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"hybrid work","meaning":"work that combines remote and workplace-based days","translation":"làm việc kết hợp","example":"Hybrid work can reduce commuting while maintaining face-to-face contact.","synonyms":["mixed-location work"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"employee retention","meaning":"an organisation's ability to keep workers from leaving","translation":"khả năng giữ chân nhân viên","example":"Career development can improve employee retention.","synonyms":["staff retention"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"collective bargaining","meaning":"negotiation between workers' representatives and employers","translation":"thương lượng tập thể","example":"Collective bargaining can influence pay and working conditions.","synonyms":["union negotiation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"workplace autonomy","meaning":"the degree of control employees have over how they do their work","translation":"quyền tự chủ nơi làm việc","example":"Greater workplace autonomy may improve motivation and job satisfaction.","synonyms":["job control"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"universal healthcare","meaning":"a system intended to provide healthcare to all residents","translation":"y tế toàn dân","example":"Universal healthcare aims to reduce financial barriers to treatment.","synonyms":["universal health coverage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"preventive medicine","meaning":"medical practice focused on stopping disease before it develops","translation":"y học dự phòng","example":"Preventive medicine can reduce long-term treatment costs.","synonyms":["preventive care"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"health inequality","meaning":"unfair differences in health outcomes between social groups","translation":"bất bình đẳng sức khỏe","example":"Income and housing conditions contribute to health inequality.","synonyms":["health disparity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"healthcare capacity","meaning":"the amount of care a health system can provide","translation":"năng lực hệ thống y tế","example":"Hospital expansion may be needed when healthcare capacity is insufficient.","synonyms":["medical capacity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"medical ethics","meaning":"principles used to judge what is right in healthcare","translation":"đạo đức y khoa","example":"Medical ethics requires respect for patients' rights and welfare.","synonyms":["healthcare ethics"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"informed consent","meaning":"agreement given after receiving and understanding relevant information","translation":"đồng thuận có hiểu biết","example":"Patients should give informed consent before major procedures.","synonyms":["informed agreement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"genetic screening","meaning":"testing used to identify inherited health risks","translation":"sàng lọc di truyền","example":"Genetic screening can help prevention but raises privacy concerns.","synonyms":["genetic testing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"organ donation","meaning":"the giving of an organ for transplantation","translation":"hiến tạng","example":"Public campaigns may increase organ donation rates.","synonyms":["organ giving"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"public-health intervention","meaning":"an organised action intended to improve population health","translation":"can thiệp y tế công cộng","example":"Vaccination is a common public-health intervention.","synonyms":["population-health measure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"patient autonomy","meaning":"a patient's right to make informed decisions about treatment","translation":"quyền tự quyết của bệnh nhân","example":"Patient autonomy can conflict with professional medical advice.","synonyms":["patient choice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"healthcare rationing","meaning":"the allocation of limited medical resources among competing needs","translation":"phân bổ hạn chế nguồn lực y tế","example":"Healthcare rationing becomes difficult when expensive treatments offer small benefits.","synonyms":["medical resource allocation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"medical innovation","meaning":"the development of new treatments, tools or healthcare methods","translation":"đổi mới y học","example":"Medical innovation can improve outcomes but may increase costs.","synonyms":["health innovation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"disease burden","meaning":"the overall impact of disease on a population","translation":"gánh nặng bệnh tật","example":"Preventive policies can reduce the national disease burden.","synonyms":["health burden"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"mental-health provision","meaning":"the services and resources available for mental healthcare","translation":"cung ứng dịch vụ sức khỏe tinh thần","example":"Mental-health provision remains inadequate in many regions.","synonyms":["mental-health services"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"recidivism","meaning":"the tendency of convicted offenders to commit crimes again","translation":"tái phạm","example":"Education and employment programmes may reduce recidivism.","synonyms":["repeat offending"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"restorative justice","meaning":"an approach that focuses on repairing harm between offenders, victims and communities","translation":"tư pháp phục hồi","example":"Restorative justice can be useful for some non-violent offences.","synonyms":["repair-based justice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"custodial sentence","meaning":"a punishment requiring an offender to stay in prison","translation":"án giam giữ","example":"Courts reserve long custodial sentences for serious crimes.","synonyms":["prison term"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"non-custodial sentence","meaning":"a punishment that does not require imprisonment","translation":"hình phạt không giam giữ","example":"A non-custodial sentence may include supervision or unpaid work.","synonyms":["community-based sentence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"reintegration","meaning":"the process of helping someone return successfully to society","translation":"tái hòa nhập","example":"Stable housing and work support prisoner reintegration.","synonyms":["social reintegration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"correctional system","meaning":"the institutions responsible for prisons, supervision and offender reform","translation":"hệ thống cải huấn","example":"The correctional system should balance security with rehabilitation.","synonyms":["penal system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"proportional punishment","meaning":"a penalty matched to the seriousness of an offence","translation":"hình phạt tương xứng","example":"Proportional punishment is a basic principle of fair justice.","synonyms":["proportionate penalty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"crime prevention","meaning":"action designed to stop crime before it occurs","translation":"phòng ngừa tội phạm","example":"Youth services can contribute to long-term crime prevention.","synonyms":["preventive policing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"sentencing policy","meaning":"official principles used when deciding criminal penalties","translation":"chính sách tuyên án","example":"Sentencing policy should be consistent while allowing judicial judgement.","synonyms":["penalty policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"prison overcrowding","meaning":"a condition in which prisons hold more people than they were designed for","translation":"quá tải nhà tù","example":"Prison overcrowding can worsen safety and rehabilitation outcomes.","synonyms":["overcrowded prisons"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"rehabilitation programme","meaning":"an organised scheme intended to help offenders change behaviour","translation":"chương trình cải tạo","example":"A rehabilitation programme may include counselling and job training.","synonyms":["offender-reform programme"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"juvenile offender","meaning":"a young person who commits an offence","translation":"người phạm tội vị thành niên","example":"Juvenile offenders often require education-focused interventions.","synonyms":["young offender"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"legal aid","meaning":"professional legal help provided free or at low cost","translation":"trợ giúp pháp lý","example":"Legal aid helps low-income defendants access representation.","synonyms":["subsidised legal support"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"wrongful conviction","meaning":"a court decision that incorrectly finds an innocent person guilty","translation":"kết án oan","example":"Reliable evidence procedures reduce the risk of wrongful conviction.","synonyms":["miscarriage of justice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban planning","meaning":"the process of designing and managing the development of towns and cities","translation":"quy hoạch đô thị","example":"Urban planning should coordinate housing, transport and green space.","synonyms":["city planning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"mixed-use development","meaning":"an area combining homes, shops, offices and other functions","translation":"phát triển đa chức năng","example":"Mixed-use development can reduce the need for long car journeys.","synonyms":["multi-purpose development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"walkability","meaning":"the extent to which an area is safe and convenient for walking","translation":"khả năng đi bộ thuận tiện","example":"Improving walkability can support public health and local business.","synonyms":["pedestrian friendliness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"transit-oriented development","meaning":"urban development concentrated around high-quality public transport","translation":"phát triển định hướng giao thông công cộng","example":"Transit-oriented development can reduce car dependence.","synonyms":["public-transport-led development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban density","meaning":"the number of people or buildings within a given urban area","translation":"mật độ đô thị","example":"Higher urban density can make public transport more efficient.","synonyms":["city density"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"zoning","meaning":"rules controlling how land in different areas may be used","translation":"phân vùng sử dụng đất","example":"Flexible zoning can allow more housing near employment centres.","synonyms":["land-use regulation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"pedestrianisation","meaning":"the process of restricting vehicles so an area is mainly for people on foot","translation":"phố đi bộ hóa","example":"Pedestrianisation can improve air quality in historic centres.","synonyms":["car-free conversion"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban regeneration","meaning":"the renewal and improvement of declining urban areas","translation":"tái thiết đô thị","example":"Urban regeneration should avoid forcing long-term residents out.","synonyms":["city renewal"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"social housing","meaning":"homes provided or supported for people who cannot afford market prices","translation":"nhà ở xã hội","example":"Social housing can reduce severe housing insecurity.","synonyms":["public housing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"compact city","meaning":"an urban model that concentrates development to limit sprawl","translation":"thành phố nén","example":"A compact city can shorten travel distances and protect surrounding land.","synonyms":["dense-city model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"sustainable mobility","meaning":"ways of travelling that reduce environmental and social costs","translation":"di chuyển bền vững","example":"Cycling and public transit are central to sustainable mobility.","synonyms":["green transport"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"heat island effect","meaning":"higher temperatures in cities caused by buildings, roads and limited vegetation","translation":"hiệu ứng đảo nhiệt đô thị","example":"More trees can reduce the urban heat island effect.","synonyms":["urban heat effect"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"resilient infrastructure","meaning":"infrastructure designed to withstand and recover from shocks","translation":"hạ tầng có khả năng chống chịu","example":"Flood-prone cities need resilient infrastructure.","synonyms":["robust infrastructure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban liveability","meaning":"the overall quality and comfort of life in a city","translation":"khả năng đáng sống của đô thị","example":"Affordable housing and green space improve urban liveability.","synonyms":["city quality of life"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"economic interdependence","meaning":"a situation in which economies rely on one another","translation":"sự phụ thuộc kinh tế lẫn nhau","example":"Trade has increased economic interdependence among countries.","synonyms":["mutual economic dependence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"cross-border trade","meaning":"trade that takes place between different countries","translation":"thương mại xuyên biên giới","example":"Digital platforms have made cross-border trade easier for small firms.","synonyms":["international commerce"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"geopolitical tension","meaning":"conflict or strained relations between countries over power and interests","translation":"căng thẳng địa chính trị","example":"Geopolitical tension can disrupt energy and food markets.","synonyms":["international tension"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"trade protectionism","meaning":"policies that restrict imports to protect domestic producers","translation":"chủ nghĩa bảo hộ thương mại","example":"Trade protectionism may protect jobs temporarily but raise consumer prices.","synonyms":["protectionist policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"global supply chain","meaning":"an international network involved in producing and delivering goods","translation":"chuỗi cung ứng toàn cầu","example":"Pandemics and conflict can expose weaknesses in global supply chains.","synonyms":["international supply network"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"international cooperation","meaning":"countries working together to solve shared problems","translation":"hợp tác quốc tế","example":"Climate change requires sustained international cooperation.","synonyms":["global collaboration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"multilateralism","meaning":"cooperation among several countries through shared rules or institutions","translation":"chủ nghĩa đa phương","example":"Multilateralism can help manage problems that cross national borders.","synonyms":["multi-country cooperation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"cultural homogenisation","meaning":"the process by which cultures become increasingly similar","translation":"đồng nhất hóa văn hóa","example":"Global media may contribute to cultural homogenisation.","synonyms":["cultural standardisation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"transnational corporation","meaning":"a company operating in multiple countries","translation":"tập đoàn xuyên quốc gia","example":"Transnational corporations can influence labour and environmental standards.","synonyms":["multinational corporation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"foreign direct investment","meaning":"investment made by a company or individual into business operations in another country","translation":"đầu tư trực tiếp nước ngoài","example":"Foreign direct investment can transfer capital and expertise.","synonyms":["FDI"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"diplomatic relations","meaning":"official political relations between countries","translation":"quan hệ ngoại giao","example":"Stable diplomatic relations support trade and cooperation.","synonyms":["international diplomacy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"global governance","meaning":"institutions and rules used to manage international issues","translation":"quản trị toàn cầu","example":"Global governance is challenging because states have different interests.","synonyms":["international governance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"economic sanctions","meaning":"official restrictions intended to pressure another country economically","translation":"trừng phạt kinh tế","example":"Economic sanctions can affect ordinary consumers as well as governments.","synonyms":["trade restrictions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"soft power","meaning":"the ability to influence others through culture, values and attraction rather than force","translation":"quyền lực mềm","example":"Universities, media and culture can contribute to a country's soft power.","synonyms":["cultural influence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"educational equity","meaning":"fair access to high-quality education regardless of background","translation":"công bằng giáo dục","example":"Educational equity requires extra support for disadvantaged learners.","synonyms":["fairness in education"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"learning outcomes","meaning":"the knowledge and abilities students gain from education","translation":"kết quả học tập","example":"Policy should focus on learning outcomes rather than enrolment alone.","synonyms":["educational results"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"standardised testing","meaning":"testing administered and scored in the same way for all students","translation":"kiểm tra chuẩn hóa","example":"Standardised testing can provide comparable data but may narrow teaching.","synonyms":["uniform testing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"academic integrity","meaning":"honest and responsible behaviour in study and research","translation":"liêm chính học thuật","example":"Generative AI has created new challenges for academic integrity.","synonyms":["academic honesty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"inclusive education","meaning":"education designed to include learners with different needs and backgrounds","translation":"giáo dục hòa nhập","example":"Inclusive education requires accessible materials and trained teachers.","synonyms":["inclusive schooling"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"early childhood education","meaning":"formal or organised learning for young children before primary school","translation":"giáo dục mầm non","example":"High-quality early childhood education can improve later outcomes.","synonyms":["preschool education"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"teacher retention","meaning":"the ability of a school system to keep qualified teachers","translation":"khả năng giữ chân giáo viên","example":"Workload and pay strongly influence teacher retention.","synonyms":["staff retention in schools"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"education reform","meaning":"major changes intended to improve an education system","translation":"cải cách giáo dục","example":"Education reform should be evaluated over several years.","synonyms":["school reform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"lifelong learning","meaning":"continuous learning throughout adulthood and working life","translation":"học tập suốt đời","example":"Lifelong learning is increasingly important in a changing labour market.","synonyms":["continuous education"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"digital pedagogy","meaning":"teaching methods that use digital technologies effectively","translation":"phương pháp sư phạm số","example":"Digital pedagogy involves more than simply moving lectures online.","synonyms":["technology-supported teaching"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"competency-based learning","meaning":"education organised around demonstrated skills and abilities","translation":"học theo năng lực","example":"Competency-based learning can allow students to progress at different speeds.","synonyms":["skills-based learning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"educational attainment","meaning":"the highest level of education a person has completed","translation":"trình độ học vấn","example":"Educational attainment is associated with employment and health outcomes.","synonyms":["education level"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"curriculum reform","meaning":"changes to what and how schools teach","translation":"cải cách chương trình học","example":"Curriculum reform may add digital skills and climate education.","synonyms":["course reform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"skills-based education","meaning":"education focused strongly on practical and transferable abilities","translation":"giáo dục định hướng kỹ năng","example":"Skills-based education can improve the transition from school to work.","synonyms":["competency-focused education"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"media literacy","meaning":"the ability to analyse, evaluate and create media messages critically","translation":"năng lực truyền thông","example":"Media literacy helps people identify unreliable online claims.","synonyms":["media competence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"disinformation","meaning":"false information deliberately created or shared to mislead","translation":"thông tin sai lệch có chủ ý","example":"Disinformation can undermine trust in elections and public health.","synonyms":["deliberate falsehood"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"misinformation","meaning":"false or inaccurate information shared regardless of intent","translation":"thông tin sai lệch","example":"Misinformation spreads quickly during fast-moving events.","synonyms":["false information"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"echo chamber","meaning":"an environment where people mainly encounter views similar to their own","translation":"buồng vang thông tin","example":"Social networks can create echo chambers around political issues.","synonyms":["closed information environment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"filter bubble","meaning":"a personalised information environment that limits exposure to different views","translation":"bong bóng lọc","example":"Recommendation systems may place users inside a filter bubble.","synonyms":["personalised information bubble"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"fact-checking","meaning":"the process of verifying whether claims are accurate","translation":"kiểm chứng thông tin","example":"Independent fact-checking can reduce the reach of false claims.","synonyms":["verification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"source credibility","meaning":"the degree to which an information source is trustworthy","translation":"độ tin cậy của nguồn","example":"Students should evaluate source credibility before citing online material.","synonyms":["source reliability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"editorial independence","meaning":"freedom of editors and journalists from improper outside influence","translation":"độc lập biên tập","example":"Editorial independence is important for trustworthy journalism.","synonyms":["journalistic independence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"information overload","meaning":"difficulty caused by receiving more information than can be processed effectively","translation":"quá tải thông tin","example":"Information overload can make it harder to identify important facts.","synonyms":["excess information"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"viral content","meaning":"online material that spreads extremely quickly between users","translation":"nội dung lan truyền","example":"Viral content is not necessarily accurate or valuable.","synonyms":["widely shared content"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"clickbait","meaning":"online headlines or content designed mainly to attract clicks","translation":"tiêu đề câu nhấp","example":"Clickbait may increase traffic while reducing trust in a news source.","synonyms":["attention-grabbing headline"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"media bias","meaning":"systematic favouring of particular viewpoints in media coverage","translation":"thiên lệch truyền thông","example":"Media bias can influence how audiences interpret political events.","synonyms":["reporting bias"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"digital citizenship","meaning":"responsible and informed participation in digital environments","translation":"công dân số","example":"Schools increasingly teach digital citizenship alongside technical skills.","synonyms":["responsible online participation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"platform moderation","meaning":"the process of enforcing rules about content on online platforms","translation":"kiểm duyệt nền tảng","example":"Platform moderation must balance safety, transparency and freedom of expression.","synonyms":["content moderation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural assimilation","meaning":"the process of adopting the dominant culture and losing some original differences","translation":"đồng hóa văn hóa","example":"Strong pressure for cultural assimilation may weaken minority languages.","synonyms":["assimilation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural preservation","meaning":"efforts to maintain traditions, languages and heritage","translation":"bảo tồn văn hóa","example":"Cultural preservation can coexist with economic modernisation.","synonyms":["heritage preservation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural appropriation","meaning":"the adoption of cultural elements in ways viewed as disrespectful or exploitative","translation":"chiếm dụng văn hóa","example":"Debates about cultural appropriation often involve power and historical context.","synonyms":["cultural misuse"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"collective identity","meaning":"a shared sense of belonging to a social group","translation":"bản sắc tập thể","example":"National events can strengthen collective identity.","synonyms":["group identity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"social cohesion","meaning":"the strength of relationships, trust and solidarity within a society","translation":"gắn kết xã hội","example":"Severe inequality can weaken social cohesion.","synonyms":["social unity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural norms","meaning":"shared expectations about acceptable behaviour within a culture","translation":"chuẩn mực văn hóa","example":"Cultural norms change across generations and social groups.","synonyms":["social conventions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"intergenerational conflict","meaning":"disagreement or tension between age groups","translation":"xung đột thế hệ","example":"Rapid technological change can intensify intergenerational conflict.","synonyms":["generation conflict"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural hybridity","meaning":"the blending of elements from different cultures","translation":"lai ghép văn hóa","example":"Migration and global media contribute to cultural hybridity.","synonyms":["cultural blending"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"minority community","meaning":"a social group smaller in number or power than the dominant population","translation":"cộng đồng thiểu số","example":"Minority communities may need support to maintain language and traditions.","synonyms":["minority group"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"social integration","meaning":"the process of enabling people from different backgrounds to participate together in society","translation":"hội nhập xã hội","example":"Employment and language skills can support social integration.","synonyms":["social inclusion"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"value system","meaning":"a set of principles used to judge what is important or right","translation":"hệ giá trị","example":"A society's value system may evolve as economic conditions change.","synonyms":["set of values"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"secularisation","meaning":"the process by which religion becomes less influential in public and social life","translation":"thế tục hóa","example":"Secularisation has changed some public institutions and family traditions.","synonyms":["declining religious influence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural continuity","meaning":"the preservation and transmission of culture across time","translation":"tính liên tục văn hóa","example":"Language education can support cultural continuity.","synonyms":["cultural transmission"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"social identity","meaning":"the part of a person's identity derived from membership in social groups","translation":"bản sắc xã hội","example":"Social identity can influence attitudes and behaviour.","synonyms":["group-based identity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"demographic transition","meaning":"the long-term shift from high birth and death rates to lower rates","translation":"chuyển đổi nhân khẩu học","example":"Demographic transition changes labour markets and pension needs.","synonyms":["population transition"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"fertility decline","meaning":"a sustained decrease in the number of children born","translation":"suy giảm mức sinh","example":"Fertility decline can accelerate population ageing.","synonyms":["falling birth rate"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"population ageing","meaning":"an increase in the proportion of older people in a population","translation":"già hóa dân số","example":"Population ageing places pressure on healthcare and pensions.","synonyms":["demographic ageing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"dependency ratio","meaning":"the number of dependants relative to the working-age population","translation":"tỷ lệ phụ thuộc","example":"A rising dependency ratio can increase pressure on public finances.","synonyms":["dependent-to-worker ratio"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"skilled migration","meaning":"movement of workers with specialised education or expertise","translation":"di cư lao động có kỹ năng","example":"Skilled migration can help address shortages in healthcare and engineering.","synonyms":["high-skill migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"refugee","meaning":"a person forced to leave a country because of war, persecution or danger","translation":"người tị nạn","example":"Refugees often need housing, language support and access to work.","synonyms":["displaced person"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"asylum seeker","meaning":"a person asking another country for legal protection as a refugee","translation":"người xin tị nạn","example":"Asylum seekers may wait months for their claims to be assessed.","synonyms":["protection applicant"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"migration policy","meaning":"government rules governing immigration, emigration and settlement","translation":"chính sách di cư","example":"Migration policy must balance economic needs with social capacity.","synonyms":["immigration policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"labour migration","meaning":"movement of people primarily for employment","translation":"di cư lao động","example":"Labour migration can benefit both sending and receiving economies.","synonyms":["work migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"remittance","meaning":"money sent by migrants to people in their home country","translation":"kiều hối","example":"Remittances support many households in lower-income countries.","synonyms":["money transfer home"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"population density","meaning":"the number of people living within a given area","translation":"mật độ dân số","example":"High population density can support efficient transit but increase housing pressure.","synonyms":["people per area"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"demographic pressure","meaning":"social or economic strain created by population change","translation":"áp lực nhân khẩu học","example":"Rapid ageing creates demographic pressure on pension systems.","synonyms":["population pressure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"migration flow","meaning":"the movement of people between regions or countries over time","translation":"dòng di cư","example":"Economic crises can alter migration flows quickly.","synonyms":["movement of migrants"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"integration policy","meaning":"government measures intended to support migrants' participation in society","translation":"chính sách hội nhập","example":"Effective integration policy often includes language and employment support.","synonyms":["inclusion policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research ethics","meaning":"principles governing responsible and humane research","translation":"đạo đức nghiên cứu","example":"Research ethics are essential when studies involve human participants.","synonyms":["ethical research principles"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"peer review","meaning":"evaluation of research by other experts in the same field","translation":"phản biện đồng cấp","example":"Peer review can identify weaknesses before research is published.","synonyms":["expert review"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"scientific consensus","meaning":"broad agreement among relevant scientific experts","translation":"đồng thuận khoa học","example":"Policy makers should understand the strength of scientific consensus.","synonyms":["expert agreement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"data integrity","meaning":"the accuracy, consistency and reliability of data","translation":"tính toàn vẹn dữ liệu","example":"Poor data integrity can invalidate research findings.","synonyms":["reliable data"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research misconduct","meaning":"serious unethical behaviour in research, such as fabrication or plagiarism","translation":"sai phạm nghiên cứu","example":"Universities need clear procedures for investigating research misconduct.","synonyms":["scientific misconduct"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"clinical trial","meaning":"a controlled study testing a medical treatment on human participants","translation":"thử nghiệm lâm sàng","example":"Clinical trials must balance potential benefits with participant safety.","synonyms":["medical trial"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"gene editing","meaning":"technology used to make targeted changes to genetic material","translation":"chỉnh sửa gen","example":"Gene editing may treat inherited disease but raises ethical questions.","synonyms":["genetic modification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"biotechnology","meaning":"the use of biological systems to develop products and technologies","translation":"công nghệ sinh học","example":"Biotechnology has applications in medicine, agriculture and industry.","synonyms":["biotech"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"scientific uncertainty","meaning":"limits in current scientific knowledge or confidence","translation":"bất định khoa học","example":"Scientific uncertainty should be communicated honestly rather than ignored.","synonyms":["uncertainty in evidence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"risk assessment","meaning":"a systematic process for identifying and evaluating possible harm","translation":"đánh giá rủi ro","example":"New technologies should undergo careful risk assessment.","synonyms":["risk evaluation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"ethical dilemma","meaning":"a situation involving a difficult choice between competing moral principles","translation":"tình huống tiến thoái lưỡng nan về đạo đức","example":"Medical professionals often face ethical dilemmas involving patient choice and public safety.","synonyms":["moral dilemma"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"evidence base","meaning":"the body of reliable research supporting a decision or practice","translation":"cơ sở bằng chứng","example":"Public-health recommendations should rest on a strong evidence base.","synonyms":["research foundation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research transparency","meaning":"openness about research methods, data and limitations","translation":"minh bạch nghiên cứu","example":"Research transparency makes scientific claims easier to evaluate.","synonyms":["open research"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"cybersecurity","meaning":"the protection of computer systems and networks from digital attacks","translation":"an ninh mạng","example":"Cybersecurity is essential for banks, hospitals and public services.","synonyms":["digital security"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data breach","meaning":"an incident in which protected information is accessed or exposed without permission","translation":"rò rỉ dữ liệu","example":"A major data breach can damage public trust in a company.","synonyms":["information leak"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"personal data protection","meaning":"rules and practices used to safeguard information about individuals","translation":"bảo vệ dữ liệu cá nhân","example":"Personal data protection should apply to both businesses and governments.","synonyms":["privacy protection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"surveillance","meaning":"systematic monitoring of people's activities or communications","translation":"giám sát","example":"Digital surveillance can improve security but threaten privacy.","synonyms":["monitoring"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"encryption","meaning":"the process of converting information into a protected coded form","translation":"mã hóa","example":"Strong encryption helps prevent unauthorised access to private messages.","synonyms":["data encoding"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"digital footprint","meaning":"the record of information created by a person's online activity","translation":"dấu vết số","example":"Young people should understand that their digital footprint can persist for years.","synonyms":["online trace"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"cybercrime","meaning":"crime carried out using computers or networks","translation":"tội phạm mạng","example":"Cybercrime creates financial and security risks for individuals and organisations.","synonyms":["online crime"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"identity theft","meaning":"the crime of using another person's personal information without permission","translation":"đánh cắp danh tính","example":"Data leaks can increase the risk of identity theft.","synonyms":["identity fraud"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"biometric data","meaning":"personal information based on physical or behavioural characteristics","translation":"dữ liệu sinh trắc học","example":"Biometric data requires strong protection because it cannot easily be changed.","synonyms":["biometric information"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"consent management","meaning":"systems for recording and respecting users' choices about data use","translation":"quản lý sự đồng thuận","example":"Clear consent management can give users more control over personal information.","synonyms":["permission management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data governance","meaning":"rules and responsibilities for collecting, storing and using data","translation":"quản trị dữ liệu","example":"Effective data governance improves privacy, quality and accountability.","synonyms":["information governance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"online anonymity","meaning":"the ability to use the internet without revealing one's real identity","translation":"ẩn danh trực tuyến","example":"Online anonymity can protect vulnerable users but also enable abuse.","synonyms":["digital anonymity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"information security","meaning":"the protection of information from unauthorised access, loss or damage","translation":"bảo mật thông tin","example":"Organisations need staff training as well as technology for information security.","synonyms":["data security"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"food security","meaning":"reliable access to sufficient, safe and nutritious food","translation":"an ninh lương thực","example":"Climate shocks can threaten food security in vulnerable regions.","synonyms":["secure food access"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"sustainable agriculture","meaning":"farming that protects resources while maintaining long-term production","translation":"nông nghiệp bền vững","example":"Sustainable agriculture aims to protect soil, water and farm incomes.","synonyms":["sustainable farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"crop resilience","meaning":"the ability of crops to withstand drought, heat or disease","translation":"khả năng chống chịu của cây trồng","example":"Crop resilience is increasingly important under climate change.","synonyms":["resilient crops"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"soil degradation","meaning":"the decline in soil quality and productive capacity","translation":"suy thoái đất","example":"Overuse of chemicals can contribute to soil degradation.","synonyms":["soil decline"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"water-efficient farming","meaning":"agricultural methods that use water carefully and productively","translation":"canh tác tiết kiệm nước","example":"Water-efficient farming is vital in drought-prone areas.","synonyms":["water-saving agriculture"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"agricultural productivity","meaning":"the amount of farm output produced from given inputs","translation":"năng suất nông nghiệp","example":"Improved seeds can raise agricultural productivity when used responsibly.","synonyms":["farm productivity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"supply-chain resilience","meaning":"the ability of supply networks to continue operating during disruption","translation":"khả năng chống chịu chuỗi cung ứng","example":"Local storage can improve food supply-chain resilience.","synonyms":["robust supply chains"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"food sovereignty","meaning":"the principle that communities should have greater control over their food systems","translation":"chủ quyền lương thực","example":"Supporters of food sovereignty favour stronger local production.","synonyms":["local control of food systems"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"intensive farming","meaning":"farming designed to produce high output from limited land","translation":"thâm canh","example":"Intensive farming can increase yields but create environmental pressures.","synonyms":["high-input farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"regenerative agriculture","meaning":"farming practices intended to restore soil and ecosystem health","translation":"nông nghiệp tái sinh","example":"Regenerative agriculture focuses on soil quality and biodiversity.","synonyms":["restorative farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"livestock emissions","meaning":"greenhouse gases produced by farm animals and related activities","translation":"khí thải chăn nuôi","example":"Diet changes and farm technology may reduce livestock emissions.","synonyms":["animal-farming emissions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"food affordability","meaning":"the extent to which people can reasonably pay for adequate food","translation":"khả năng chi trả thực phẩm","example":"Inflation can sharply reduce food affordability for poor households.","synonyms":["affordable food access"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"crop diversity","meaning":"the variety of crops grown within a farming system","translation":"đa dạng cây trồng","example":"Crop diversity can reduce vulnerability to pests and climate shocks.","synonyms":["agricultural diversity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water scarcity","meaning":"a shortage of sufficient usable water","translation":"khan hiếm nước","example":"Population growth and drought can intensify water scarcity.","synonyms":["water shortage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water management","meaning":"planning and control of water resources and services","translation":"quản lý tài nguyên nước","example":"Effective water management must consider homes, farms and ecosystems.","synonyms":["water governance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"groundwater","meaning":"water stored naturally below the Earth's surface","translation":"nước ngầm","example":"Excessive groundwater extraction can lower water tables.","synonyms":["underground water"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"freshwater supply","meaning":"the available amount of non-salty water for human and ecological needs","translation":"nguồn cung nước ngọt","example":"Climate change may make freshwater supplies less predictable.","synonyms":["fresh water availability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water conservation","meaning":"efforts to reduce unnecessary water use","translation":"bảo tồn và tiết kiệm nước","example":"Water conservation can delay the need for expensive new infrastructure.","synonyms":["water saving"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"desalination","meaning":"the process of removing salt from seawater","translation":"khử mặn","example":"Desalination can increase water supply but requires substantial energy.","synonyms":["seawater treatment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"contaminated water","meaning":"water containing harmful substances or organisms","translation":"nước bị ô nhiễm","example":"Contaminated water can cause severe public-health problems.","synonyms":["polluted water"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water treatment","meaning":"processes used to make water safe or suitable for use","translation":"xử lý nước","example":"Modern water treatment protects communities from disease.","synonyms":["water purification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"drought resilience","meaning":"the ability to withstand and recover from long dry periods","translation":"khả năng chống chịu hạn hán","example":"Drought resilience requires efficient irrigation and diversified water sources.","synonyms":["resilience to drought"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"river basin","meaning":"the land area drained by a river and its tributaries","translation":"lưu vực sông","example":"Water policy should often be coordinated across an entire river basin.","synonyms":["watershed"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water infrastructure","meaning":"systems for storing, treating and delivering water","translation":"hạ tầng nước","example":"Ageing water infrastructure can lead to leaks and service failures.","synonyms":["water systems"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water allocation","meaning":"the process of deciding how available water is shared among users","translation":"phân bổ nước","example":"Water allocation becomes contentious during severe droughts.","synonyms":["distribution of water"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"sanitation","meaning":"systems and practices for safely managing human waste and hygiene","translation":"vệ sinh môi trường","example":"Improved sanitation has major benefits for health and development.","synonyms":["public hygiene"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"sustainable development","meaning":"development that meets current needs without undermining future generations","translation":"phát triển bền vững","example":"Sustainable development integrates economic, social and environmental goals.","synonyms":["long-term development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"development aid","meaning":"money or resources provided to support development in poorer regions","translation":"viện trợ phát triển","example":"Development aid is most effective when aligned with local priorities.","synonyms":["foreign aid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"humanitarian assistance","meaning":"emergency help provided during conflict, disaster or severe crisis","translation":"hỗ trợ nhân đạo","example":"Humanitarian assistance can provide food, shelter and medical care.","synonyms":["emergency aid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"poverty reduction","meaning":"policies and actions aimed at decreasing poverty","translation":"giảm nghèo","example":"Education and employment are central to long-term poverty reduction.","synonyms":["anti-poverty action"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"infrastructure investment","meaning":"spending on systems such as roads, energy, water and communications","translation":"đầu tư cơ sở hạ tầng","example":"Infrastructure investment can improve productivity and regional access.","synonyms":["capital investment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"capacity building","meaning":"efforts to strengthen the skills and institutions needed to solve problems","translation":"xây dựng năng lực","example":"Capacity building can make development programmes more sustainable.","synonyms":["institutional strengthening"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"developing economy","meaning":"an economy with lower average income and ongoing structural development","translation":"nền kinh tế đang phát triển","example":"Developing economies may face different infrastructure and employment challenges.","synonyms":["emerging economy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"aid dependency","meaning":"a situation in which a country or organisation relies heavily on external aid","translation":"phụ thuộc viện trợ","example":"Poorly designed assistance can create long-term aid dependency.","synonyms":["reliance on aid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"development programme","meaning":"an organised set of projects intended to improve economic or social conditions","translation":"chương trình phát triển","example":"A development programme should include clear measures of success.","synonyms":["development initiative"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"global poverty","meaning":"severe economic deprivation affecting people across the world","translation":"nghèo đói toàn cầu","example":"Economic shocks can slow progress against global poverty.","synonyms":["world poverty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"human development","meaning":"improvement in people's health, education, capabilities and living conditions","translation":"phát triển con người","example":"Income growth alone does not guarantee human development.","synonyms":["people-centred development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"public-private partnership","meaning":"cooperation between government and private companies to deliver projects or services","translation":"hợp tác công tư","example":"A public-private partnership can mobilise investment for infrastructure.","synonyms":["PPP"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"economic inclusion","meaning":"the ability of people to participate in and benefit from economic activity","translation":"hòa nhập kinh tế","example":"Financial access and skills training can support economic inclusion.","synonyms":["inclusive participation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal welfare","meaning":"the physical and psychological well-being of animals","translation":"phúc lợi động vật","example":"Animal welfare standards should apply to farms, laboratories and zoos.","synonyms":["well-being of animals"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal testing","meaning":"the use of animals in scientific or product experiments","translation":"thử nghiệm trên động vật","example":"Animal testing remains controversial in medical research.","synonyms":["animal experimentation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"factory farming","meaning":"large-scale intensive systems for raising animals for food","translation":"chăn nuôi công nghiệp","example":"Factory farming raises concerns about welfare and environmental impact.","synonyms":["industrial livestock farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal rights","meaning":"the view that animals deserve moral and legal protection","translation":"quyền động vật","example":"Supporters of animal rights oppose many forms of animal exploitation.","synonyms":["rights of animals"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"wildlife trafficking","meaning":"the illegal trade in wild animals or animal products","translation":"buôn bán động vật hoang dã","example":"Wildlife trafficking threatens endangered species.","synonyms":["illegal wildlife trade"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"captivity","meaning":"the condition of being kept confined rather than free","translation":"tình trạng nuôi nhốt","example":"Large animals may suffer when kept in unsuitable captivity.","synonyms":["confinement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"humane treatment","meaning":"care that avoids unnecessary pain or cruelty","translation":"đối xử nhân đạo","example":"Consumers increasingly demand humane treatment of farm animals.","synonyms":["compassionate treatment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"ethical consumption","meaning":"buying choices influenced by moral, social or environmental concerns","translation":"tiêu dùng có đạo đức","example":"Ethical consumption can pressure companies to improve supply chains.","synonyms":["responsible consumption"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"cruelty","meaning":"behaviour that causes unnecessary suffering","translation":"sự tàn nhẫn","example":"Laws should prevent cruelty to animals.","synonyms":["inhumane treatment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"endangered-species protection","meaning":"measures designed to prevent threatened species from disappearing","translation":"bảo vệ loài nguy cấp","example":"Endangered-species protection requires habitat conservation and law enforcement.","synonyms":["species protection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"laboratory animal","meaning":"an animal used in scientific research","translation":"động vật thí nghiệm","example":"Researchers must minimise suffering when using laboratory animals.","synonyms":["research animal"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"veganism","meaning":"a lifestyle that avoids animal products, especially in food","translation":"chủ nghĩa thuần chay","example":"Some people adopt veganism for ethical or environmental reasons.","synonyms":["plant-based lifestyle"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal exploitation","meaning":"the use of animals primarily for human benefit in ways considered unfair or harmful","translation":"khai thác động vật","example":"Critics argue that certain entertainment practices involve animal exploitation.","synonyms":["harmful use of animals"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space exploration","meaning":"the investigation of space using humans, robots or scientific instruments","translation":"khám phá vũ trụ","example":"Space exploration can expand scientific knowledge and drive innovation.","synonyms":["space investigation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space programme","meaning":"a national or organisational effort involving space missions and research","translation":"chương trình không gian","example":"A national space programme requires substantial long-term funding.","synonyms":["space initiative"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"satellite technology","meaning":"technology involving artificial objects placed in orbit","translation":"công nghệ vệ tinh","example":"Satellite technology supports navigation, weather forecasting and communication.","synonyms":["satellite systems"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space mission","meaning":"an organised journey or operation carried out in space","translation":"sứ mệnh không gian","example":"A space mission may take years of planning and testing.","synonyms":["space expedition"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"astronomy","meaning":"the scientific study of stars, planets and the universe","translation":"thiên văn học","example":"Astronomy helps scientists understand the origins of the universe.","synonyms":["space science"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"scientific discovery","meaning":"a new finding that increases scientific knowledge","translation":"khám phá khoa học","example":"Space telescopes have enabled major scientific discoveries.","synonyms":["research discovery"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space tourism","meaning":"commercial travel into space for private passengers","translation":"du lịch vũ trụ","example":"Space tourism raises concerns about cost, safety and emissions.","synonyms":["commercial space travel"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"orbital debris","meaning":"human-made objects and fragments left in Earth orbit","translation":"rác vũ trụ","example":"Orbital debris can damage satellites and spacecraft.","synonyms":["space debris"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"planetary research","meaning":"scientific investigation of planets and related bodies","translation":"nghiên cứu hành tinh","example":"Planetary research may reveal whether other worlds once supported life.","synonyms":["planetary science"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space agency","meaning":"a public organisation responsible for space research and missions","translation":"cơ quan vũ trụ","example":"National space agencies often cooperate on major missions.","synonyms":["space authority"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"public investment in space","meaning":"government spending on space science and technology","translation":"đầu tư công vào vũ trụ","example":"Public investment in space is often debated when social needs are urgent.","synonyms":["government space spending"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"technological spin-off","meaning":"a useful technology developed from research for another purpose","translation":"công nghệ phái sinh","example":"Space research has produced technological spin-offs used in everyday life.","synonyms":["research spin-off"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"extraterrestrial life","meaning":"life that may exist beyond Earth","translation":"sự sống ngoài Trái Đất","example":"The search for extraterrestrial life remains a major scientific question.","synonyms":["alien life"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"corporate social responsibility","meaning":"a company's responsibility for its social and environmental effects","translation":"trách nhiệm xã hội doanh nghiệp","example":"Corporate social responsibility can improve trust when backed by real action.","synonyms":["CSR"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"corporate governance","meaning":"the system by which companies are directed and controlled","translation":"quản trị doanh nghiệp","example":"Strong corporate governance can reduce conflicts of interest.","synonyms":["company governance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"environmental social governance","meaning":"a framework for evaluating environmental, social and governance performance","translation":"môi trường xã hội và quản trị","example":"Investors increasingly examine environmental, social and governance risks.","synonyms":["ESG"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"ethical business","meaning":"business activity guided by fair and responsible principles","translation":"kinh doanh có đạo đức","example":"Ethical business practices can strengthen long-term customer trust.","synonyms":["responsible business"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"greenwashing","meaning":"misleading claims that make a product or company appear more environmentally responsible","translation":"tẩy xanh","example":"Greenwashing can make it difficult for consumers to identify genuinely sustainable products.","synonyms":["false green claims"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"corporate accountability","meaning":"the obligation of companies to explain and take responsibility for their impacts","translation":"trách nhiệm giải trình doanh nghiệp","example":"Corporate accountability should extend across global supply chains.","synonyms":["business accountability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"stakeholder capitalism","meaning":"a model in which companies consider employees, communities and other stakeholders as well as shareholders","translation":"chủ nghĩa tư bản vì các bên liên quan","example":"Stakeholder capitalism argues that firms have duties beyond profit.","synonyms":["stakeholder model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"sustainable finance","meaning":"financial activity that considers long-term environmental and social outcomes","translation":"tài chính bền vững","example":"Sustainable finance can direct capital toward low-carbon projects.","synonyms":["green finance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"responsible investment","meaning":"investment decisions that consider ethical, social or environmental factors","translation":"đầu tư có trách nhiệm","example":"Responsible investment has grown among large pension funds.","synonyms":["ethical investment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"supply-chain ethics","meaning":"ethical standards applied to suppliers, sourcing and production networks","translation":"đạo đức chuỗi cung ứng","example":"Supply-chain ethics includes labour rights and environmental standards.","synonyms":["ethical sourcing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"business ethics","meaning":"moral principles governing commercial decisions and behaviour","translation":"đạo đức kinh doanh","example":"Business ethics should guide advertising, employment and data practices.","synonyms":["corporate ethics"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"corporate transparency","meaning":"openness by companies about decisions, performance and impacts","translation":"minh bạch doanh nghiệp","example":"Corporate transparency helps investors and consumers evaluate claims.","synonyms":["business openness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"social impact","meaning":"the effect of an organisation or activity on people and communities","translation":"tác động xã hội","example":"Companies increasingly measure social impact alongside financial performance.","synonyms":["societal effect"]}]$json$::jsonb) AS x(
    "groupKey" TEXT, "groupName" TEXT, "topicName" TEXT, "word" TEXT, "meaning" TEXT, "translation" TEXT, "example" TEXT, "synonyms" JSONB
  )
)
INSERT INTO "VocabularyWord" ("id", "topicId", "word", "meaning", "example", "translation", "synonyms", "createdAt", "updatedAt")
SELECT
  'vw_' || md5(wd."groupKey" || '|' || wd."topicName" || '|' || lower(wd."word")),
  t."id", wd."word", wd."meaning", wd."example", wd."translation",
  ARRAY(SELECT jsonb_array_elements_text(wd."synonyms")), NOW(), NOW()
FROM word_data wd
JOIN "VocabularyGroup" g ON g."name" = wd."groupName"
JOIN "VocabularyTopic" t ON t."groupId" = g."id" AND t."name" = wd."topicName"
ON CONFLICT ("topicId", "word") DO UPDATE SET
  "meaning" = EXCLUDED."meaning",
  "example" = EXCLUDED."example",
  "translation" = EXCLUDED."translation",
  "synonyms" = EXCLUDED."synonyms",
  "updatedAt" = NOW();
